function agentsQueryOptions(slug: string) {
	return {
		queryKey: ["agents", slug] as const,
		queryFn: async (): Promise<AgentItem[]> => {
			const res = await fetchWithTimeout(agentsUrl(slug), {
				credentials: "include",
			});
			if (!res.ok) return [];
			const data = (await res.json()) as { agents?: AgentItem[] };
			return data.agents ?? [];
		},
		staleTime: 30_000,
	};
}

