const out = {};
for (const id of ['crm','lobu-builder']) {
  const r = await fetch(`/lobu/api/v1/agents/${id}/history/threads?scope=all`, {
    credentials:'include', headers:{'X-Lobu-Org':'lobu-crm'}
  });
  if (!r.ok) { out[id] = `HTTP ${r.status}`; continue; }
  const d = await r.json();
  const threads = d.threads ?? [];
  const byPlatform = {};
  for (const t of threads) byPlatform[t.platform ?? '?'] = (byPlatform[t.platform ?? '?'] ?? 0) + 1;
  out[id] = { total: threads.length, byPlatform,
    sample: threads.slice(0,6).map(t=>({p:t.platform, title:t.title, cid:t.conversationId})) };
}
