import { getDb } from './db/client';

export interface PersistedMcpSession {
  sessionId: string;
  userId: string | null;
  clientId: string | null;
  organizationId: string | null;
  memberRole: string | null;
  requestedAgentId: string | null;
  isAuthenticated: boolean;
  scopedToOrg: boolean;
  lastAccessedAt: number;
  expiresAt: number;
}

function fromDate(value: unknown): number | null {
  if (value instanceof Date) return value.getTime();
  if (typeof value === 'string') {
    const parsed = Date.parse(value);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

function fromBool(value: unknown): boolean {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value !== 0;
  if (typeof value === 'string') {
    const normalized = value.trim().toLowerCase();
    return normalized === 't' || normalized === 'true' || normalized === '1';
  }
  return false;
}

export class McpSessionStore {
  async upsertSession(session: PersistedMcpSession): Promise<void> {
    const sql = getDb();
    await sql`
      INSERT INTO mcp_sessions (
        session_id,
        user_id,
        client_id,
        organization_id,
        member_role,
        requested_agent_id,
        is_authenticated,
        scoped_to_org,
        last_accessed_at,
        expires_at
      ) VALUES (
        ${session.sessionId},
        ${session.userId},
        ${session.clientId},
        ${session.organizationId},
        ${session.memberRole},
        ${session.requestedAgentId},
        ${session.isAuthenticated},
        ${session.scopedToOrg},
        ${new Date(session.lastAccessedAt)},
        ${new Date(session.expiresAt)}

