const orgs = ['buremba','lobu-crm','lobu-team'];
const out = {};
for (const org of orgs) {
  const a = await fetch(`/api/${org}/agents`, {credentials:'include'});
  if (!a.ok) { out[org] = `agents HTTP ${a.status}`; continue; }
  const ids = ((await a.json()).agents ?? []).map(x=>x.agentId);
  let byPlatform = {}, total = 0;
  for (const id of ids) {
    const r = await fetch(`/lobu/api/v1/agents/${id}/history/threads?scope=all`, {credentials:'include', headers:{'X-Lobu-Org':org}});
    if (!r.ok) continue;
    const th = ((await r.json()).threads ?? []);
    total += th.length;
    for (const t of th) byPlatform[t.platform ?? '?'] = (byPlatform[t.platform ?? '?'] ?? 0) + 1;
  }
  out[org] = { agents: ids.length, totalThreads: total, byPlatform };
}
JSON.stringify(out, null, 1)

