 * and regenerates in the background when stale; we keep polling while it reports
 * `generating` so freshly-produced chips appear without a manual refresh. Enable
 * only on a fresh draft (no threadId) — established threads have their own chips.
 */
export function useAgentStarters(
	agentId?: string | null,
	options?: { enabled?: boolean; orgSlug?: string | null },
) {
	const { slug } = getPathScope();
	const orgSlug = options?.orgSlug ?? slug;

	return useQuery({
		queryKey: ["agent-starters", orgSlug, agentId],
		queryFn: async (): Promise<AgentStartersResponse> => {
			const res = await fetchWithTimeout(
				`${API_URL}/lobu/api/v1/agents/${agentId ?? ""}/starters`,
				{ credentials: "include", headers: orgScopedHeaders(orgSlug) },
			);
			if (res.status === 401 || res.status === 403)
				return {
					prompts: [],
					source: "agent",
					stale: false,
					generating: false,
				};
			await throwIfNotOk(res, "Failed to fetch starters");
			const data = (await res.json()) as Partial<AgentStartersResponse>;
			return {
				prompts: Array.isArray(data.prompts) ? data.prompts : [],
				source: data.source === "config" ? "config" : "agent",
				stale: Boolean(data.stale),
				generating: Boolean(data.generating),
			};
		},
		enabled: !!orgSlug && !!agentId && (options?.enabled ?? true),
		// Poll while the server is (re)generating; stop once chips have arrived.
		refetchInterval: (query) => (query.state.data?.generating ? 2_500 : false),
		staleTime: 5_000,
	});
}

