/**
 * Starter-action chips shown ABOVE the composer on a FRESH conversation (before
 * any message). Generated per agent+org by the server (AI-generated from
 * workspace state, or config `starterPrompts`); pulled here, not delivered over
 * SSE (a fresh draft has no stream yet). Only shown at zero turns and never
 * while running — once the first message is sent, post-turn `SuggestionChips`
 * takes over. Tapping a chip sends its `message` as the first user turn.
 */
const StarterChips: FC = () => {
	const { messages, running, append, agentId, workspaceSlug } = useLobuChat();
	const isFreshDraft = messages.length === 0 && !running;
	const { data } = useAgentStarters(agentId, {
		orgSlug: workspaceSlug,
		enabled: isFreshDraft,
	});
	if (!isFreshDraft || !data || data.prompts.length === 0) return null;
	return <Chips prompts={data.prompts} onPick={(message) => append(message)} />;
};

