1	/**
2	 * Integration test: the `client_id` filter scopes events to one OAuth client.
3	 *
4	 * This backs the MCP activity view — "what did ChatGPT do here" — which reads
5	 * events filtered by `client_id` plus `semantic_type: 'audit'`. `client_id` is a
6	 * real indexed column on `events` (idx_events_client_id, FK → oauth_clients),
7	 * NOT a metadata field, so the predicate is a plain column match.
8	 *
9	 * Why an integration test and not a unit one: the filter is threaded through two
10	 * SQL builders that share POSITIONAL parameter slots. `client_id` took slot $12,
11	 * which shifted every downstream index in the search path (orgScope, exclude,
12	 * visibility, entity-types, cursor…). A mismatch there typechecks perfectly and
13	 * fails only against a real Postgres — usually as a wrong-parameter bind rather
14	 * than an error, i.e. silently wrong rows. Both query paths are exercised:
15	 *
16	 *   - list path   (no search_term) — appended condition, params.length-indexed
17	 *   - search path (search_term)    — fixed $12 slot in a shared WHERE template
18	 *
19	 * A client that re-registers gets a NEW oauth_clients row under the same
20	 * client_name (verified in prod: "Lobu CLI" had 6 ids), so the filter accepts an
21	 * ARRAY and both shapes are covered.
22	 *
23	 * Vitest CI gap note (mirrors neighbors): runs locally / in the CI integration
24	 * job against the pgvector DB via DATABASE_URL.
25	 */
26	
27	import { beforeAll, describe, expect, it } from 'vitest';
28	import { getContent } from '../../../tools/get_content';
29	import type { ToolContext } from '../../../tools/registry';
30	import { initWorkspaceProvider } from '../../../workspace';
31	import { cleanupTestDatabase, getTestDb } from '../../setup/test-db';
32	import {
33	  addUserToOrganization,
34	  createTestOrganization,
35	  createTestUser,
36	  seedSystemEntityTypes,
37	} from '../../setup/test-fixtures';
38	
39	/** Register an oauth_clients row so the events FK is satisfiable. */
40	async function registerClient(opts: {
41	  id: string;
42	  clientName: string;
43	  userId: string;
44	  organizationId: string;
45	}): Promise<void> {
46	  const sql = getTestDb();
47	  await sql`
48	    INSERT INTO oauth_clients (id, client_name, redirect_uris, user_id, organization_id)
49	    VALUES (
50	      ${opts.id}, ${opts.clientName}, ARRAY['https://example.test/cb']::text[],
51	      ${opts.userId}, ${opts.organizationId}
52	    )
53	    ON CONFLICT (id) DO NOTHING
54	  `;
55	}
56	
57	/** Insert one audit-shaped event attributed to `clientId` (or none). */
58	async function insertAuditEvent(opts: {
59	  organizationId: string;
60	  title: string;
61	  clientId: string | null;
62	  occurredAt: Date;
63	}): Promise<number> {
64	  const sql = getTestDb();
65	  const [row] = await sql`
66	    INSERT INTO events (
67	      organization_id, origin_id, title, payload_type, payload_text,
68	      semantic_type, client_id, occurred_at, created_at
69	    ) VALUES (
70	      ${opts.organizationId},
71	      ${`client-filter-${opts.title}-${opts.occurredAt.getTime()}`},
72	      ${opts.title}, 'text', ${opts.title},
73	      'audit', ${opts.clientId}, ${opts.occurredAt}, NOW()
74	    )
75	    RETURNING id
76	  `;
77	  return Number((row as { id: unknown }).id);
78	}
