5	import type { Env } from '../../index';
6	import { type DbClient, pgTextArray } from '../../db/client';
7	import { buildConnectionFilter, buildFeedFilter, buildOrderByClause, buildRunFilter } from '../content-query-filters';
8	import { parseDateAlias, toEndOfDay } from '../date-aliases';
9	import { configuredEmbeddingModelSqlLiteral, generateEmbeddings } from '../embeddings';
10	import { toVectorLiteral } from '../entity-management';
11	import logger from '../logger';
12	import { validateNumericId } from '../sql-validation';
13	import { buildLatestClassificationsCteSql, buildThreadMetaCteSql } from './ctes';
14	import { buildEntityLinkUnion, entityLinkMatchSql, fetchEntityIdentityScopes } from './entity-link';
15	import {
16	  CANDIDATE_QUERY_TIMEOUT_MS,
17	  CANDIDATE_VECTOR_LIMIT,
18	  TSQUERY_SQL,
19	  buildSearchDocumentExpr,
20	  buildTsqueryString,
21	} from './fts';
22	import { buildFinalSelect, deduplicateWithClassifications } from './sql-fragments';
23	import {
24	  buildDateCandidateOrderBy,
25	  buildDateCursorClause,
26	  buildPageInfo,
27	  isDateFeedMode,
28	  resolveDateCursor,
29	  type ContentSearchOptions,
30	  type ContentSearchResponse,
31	  type ContentSearchResult,
32	} from './types';
33	import { buildEntityTypesFilterClause } from './entity-types-filter';
34	import { buildConnectionVisibilityClause, buildExcludeWatcherClause, buildOrgScopeWhere } from './visibility';
35	import { getErrorMessage } from "@lobu/core";
36	
37	export async function searchContentBySingleQuery(
38	  sql: DbClient,
39	  queryText: string,
40	  options: ContentSearchOptions & { offset?: number },
41	  env?: Env
42	): Promise<ContentSearchResponse> {
43	  const entityId = options.entity_id;
44	  const limit = Math.min(options.limit ?? 50, 500);
45	  const offset = options.offset ?? 0;
46	  const useDateFeed = isDateFeedMode(options);
47	  const cursor = resolveDateCursor(options);
48	  const effectiveOffset = useDateFeed ? 0 : offset;
49	  const fetchLimit = useDateFeed ? limit + 1 : limit;
50	  const trimmedQuery = queryText.trim();
51	
52	  let queryEmbedding: number[] | null = options.query_embedding?.length
53	    ? options.query_embedding
54	    : null;
55	  if (!queryEmbedding && env?.EMBEDDINGS_SERVICE_URL) {
56	    try {
57	      const embeddings = await generateEmbeddings([trimmedQuery], env);
58	      queryEmbedding = embeddings[0] ?? null;
59	    } catch (err) {
60	      logger.warn(
61	        { err: getErrorMessage(err) },
62	        '[content-search] Embedding generation failed, falling back to text-only search'
63	      );
64	    }
65	  }
66	  const hasEmbedding = queryEmbedding !== null;
67	  // Clamp to [0, 1] so a caller can't produce an always-true / always-false
68	  // predicate with an out-of-range value. Non-numeric input falls back to the
69	  // default. The parameter is still bound (not interpolated) below for defense
70	  // in depth.
71	  const rawMinSimilarity = Number(options.min_similarity ?? 0.3);
72	  const minSimilarity = Number.isFinite(rawMinSimilarity)
73	    ? Math.max(0, Math.min(1, rawMinSimilarity))
74	    : 0.3;
75	
76	  const sinceDate = options.since ? parseDateAlias(options.since).date : null;
77	  const untilDate = options.until ? toEndOfDay(parseDateAlias(options.until).date) : null;
78	  const connectionIdsArray =
79	    options.connection_ids && options.connection_ids.length > 0 ? options.connection_ids : null;
80	  const feedIdsArray =
81	    options.feed_ids && options.feed_ids.length > 0 ? options.feed_ids : null;
82	  const runIdsArray =
83	    options.run_ids && options.run_ids.length > 0 ? options.run_ids : null;
84	
85	  const needClassifications =
86	    options.include_classifications ||
87	    (options.classification_filters && options.classification_filters.length > 0);
88	
89	  const connectionCondition = buildConnectionFilter(connectionIdsArray);
90	  const feedCondition = buildFeedFilter(feedIdsArray);
91	  const runCondition = buildRunFilter(runIdsArray);
92	
93	  // Pre-fetch the entity's identity claims so the entity-link UNION trims
94	  // unused namespaces. Search path benefits even more than the chronological
95	  // path because filtered_ids re-evaluates on every query variant attempt.
96	  const searchEntityScopes =
97	    entityId != null ? await fetchEntityIdentityScopes(sql, entityId) : [];
98	
99	  // Slots $11/$12 are the agent_id memory-scope and client_id filters — they
100	  // bump orgScope to $13. Keep this in step with buildStandardParams: the two
101	  // param lists are positional mirrors, so an added slot shifts BOTH.
102	  const orgScope = buildOrgScopeWhere({
103	    entity_id: entityId,
104	    organization_id: options.organization_id,
105	    baseParamIndex: 12,
106	  });
107	  // Exclude-watcher param slot sits immediately after orgScope so its $N index
108	  // is stable regardless of whether an embedding param follows.
109	  const excludeParamIdx = 12 + orgScope.params.length;
110	  const excludeClause = buildExcludeWatcherClause(
111	    options.exclude_watcher_id,
112	    excludeParamIdx
113	  );
114	  // Connection-visibility predicate. Same helper used by every other
115	  // get_content branch, so authed/unauthed/private/system-event semantics
116	  // are guaranteed identical across the search/text-query path and the
117	  // chronological list path.
118	  const visibilityParamIdx = excludeParamIdx + excludeClause.params.length;
119	  const visibilityClause = buildConnectionVisibilityClause({
120	    organizationId: options.visibility_scope?.organizationId,
121	    userId: options.visibility_scope?.userId ?? null,
122	    baseParamIndex: visibilityParamIdx,
123	  });
124	  const entityTypesParamIdx = visibilityParamIdx + visibilityClause.params.length;
125	  const entityTypesClause = buildEntityTypesFilterClause({
126	    entity_types: options.entity_types,
127	    organization_id: options.organization_id,
128	    baseParamIndex: entityTypesParamIdx,
129	  });
130	  const entityLinkParamIdx = entityTypesParamIdx + entityTypesClause.params.length;
131	  // Build entity-link UNION (alias `f` for filtered_ids; alias `p` for thread
