	// Connected MCP clients (ChatGPT, Claude Desktop, the CLI …) are DERIVED the
	// same way behaviors are — from the audit trail, not a `conversations` row.
	// An MCP tool call has no run, no worker and therefore no transcript, so a
	// conversation row would list an entry that opens to nothing. These entries
	// route to the filtered events timeline instead, which is the record that
	// actually exists.
	//
	// Grouped by client_name, NOT client_id: a client mints a NEW oauth_clients
	// row every time it re-registers (prod has 6 ids for "Lobu CLI"), so keying
	// on the id would repeat one client down the sidebar. Grouping by name is
	// safe because a name maps to exactly one (user, org) — enforced by the
	// user_id/organization_id predicate below, so two users' activity can never
	// merge into one row.
	if (userId) {
		const sql = getDb();
		const clientRows = await sql<{
			client_name: string;
			client_ids: string[];
			last_at: Date;
			first_at: Date;
		}>`
      SELECT oc.client_name,
             array_agg(DISTINCT oc.id) AS client_ids,
             max(e.created_at) AS last_at,
             min(e.created_at) AS first_at
      FROM public.events e
      JOIN public.oauth_clients oc ON oc.id = e.client_id
      WHERE e.organization_id = ${organizationId}
        AND e.semantic_type = 'audit'
        AND e.client_id IS NOT NULL
        AND oc.client_name IS NOT NULL
        AND oc.user_id = ${userId}
        AND oc.organization_id = ${organizationId}
      GROUP BY oc.client_name
    `;
		for (const row of clientRows) {
			const key = `mcp_${row.client_name}`;
			byKey.set(key, {
				id: key,
				title: row.client_name,
				createdAt: row.first_at.getTime(),
				updatedAt: row.last_at.getTime(),
				platform: "mcp",
				conversationId: key,
				clientIds: row.client_ids,
			});
		}
	}

	return [...byKey.values()].sort((a, b) => b.updatedAt - a.updatedAt);
}

