import { describe, expect, it } from "vitest";
import {
	convertFiltersToApiParams,
	EVENT_FILTER_KEYS,
	hasEventCursor,
	parseEventFiltersFromUrl,
	serializeEventFiltersToSearch,
} from "./event-filters";

describe("event filters cursor support", () => {
	it("parses at cursor param from the URL", () => {
		const filters = parseEventFiltersFromUrl(
			new URLSearchParams({ at: "2026-04-07T10:00:00.000Z,42" }),
		);

		expect(filters.beforeOccurredAt).toBe("2026-04-07T10:00:00.000Z");
		expect(filters.beforeId).toBe(42);
		expect(hasEventCursor(filters)).toBe(true);
	});

	it("serializes cursor as combined at param", () => {
		const search = serializeEventFiltersToSearch({
			beforeOccurredAt: "2026-04-07T10:00:00.000Z",
			beforeId: 42,
		});

		expect(search.at).toBe("2026-04-07T10:00:00.000Z,42");
	});

	it("lists every serializable param in EVENT_FILTER_KEYS so clearing a filter drops its URL param", () => {
		// A fully-populated filter set exercises every branch of the serializer.
		// useTabFilters only deletes params in EVENT_FILTER_KEYS before re-writing,
		// so any emitted key absent from the list goes stale (the semantic_types /
		// interaction_status "All can't clear the param" bug).
		const search = serializeEventFiltersToSearch({
			platforms: ["telegram"],
			dateRange: [new Date("2026-01-01"), new Date("2026-02-01")],
			engagementRange: [10, 90],
			classificationFilters: { sentiment: ["positive"] },
			searchQuery: "hello world",
			sortBy: "date",
			sortOrder: "asc",
			reviewStatus: "user",
			semanticTypes: ["notification"],
			windowId: 7,
			entityId: 62,
			contentIds: [1, 2],
			connectionIds: [3],
			feedIds: [4],
			runIds: [5],
			agentId: "crm",
			beforeOccurredAt: "2026-04-07T10:00:00.000Z",
			beforeId: 42,
			interactionStatus: "pending",
		});

		for (const key of Object.keys(search)) {
			expect(EVENT_FILTER_KEYS).toContain(key);
		}
		expect(EVENT_FILTER_KEYS).toContain("semantic_types");
		expect(EVENT_FILTER_KEYS).toContain("interaction_status");
		expect(EVENT_FILTER_KEYS).toContain("behavior");
	});

	it("round-trips behavior through the URL and maps to analyzed_by_behavior_id", () => {
		const search = serializeEventFiltersToSearch({
			watcherId: 42,
		});
		const parsed = parseEventFiltersFromUrl(
			new URLSearchParams(
				Object.entries(search).filter(
					(entry): entry is [string, string] => entry[1] !== undefined,
				),
			),
		);
		expect(parsed.watcherId).toBe(42);
		expect(
			convertFiltersToApiParams({ watcherId: 42 }).analyzed_by_behavior_id,
		).toBe(42);
	});

	it("round-trips agent through the URL", () => {
		const search = serializeEventFiltersToSearch({
			agentId: "crm",
		});
		const parsed = parseEventFiltersFromUrl(
			new URLSearchParams(
				Object.entries(search).filter(
					(entry): entry is [string, string] => entry[1] !== undefined,
				),
			),
		);
		expect(parsed.agentId).toBe("crm");
		expect(convertFiltersToApiParams({ agentId: "crm" }).agent_id).toBe("crm");
	});

	it("round-trips connection_ids through the URL", () => {
		const search = serializeEventFiltersToSearch({
			connectionIds: [3, 7],
		});
		const parsed = parseEventFiltersFromUrl(
			new URLSearchParams(
				Object.entries(search).filter(
					(entry): entry is [string, string] => entry[1] !== undefined,
				),
			),
		);
		expect(parsed.connectionIds).toEqual([3, 7]);
	});

	it("zeros API offset when cursor navigation is active", () => {
		const params = convertFiltersToApiParams({
			page: 5,
			beforeOccurredAt: "2026-04-07T10:00:00.000Z",
			beforeId: 42,
			sortBy: "date",
			sortOrder: "desc",
		});

		expect(params.offset).toBe(0);
		expect(params.before_occurred_at).toBe("2026-04-07T10:00:00.000Z");
		expect(params.before_id).toBe(42);
	});

	it("emits include_classification (singular) for read_knowledge, never include_classifications", () => {
		// read_knowledge schema rejects unknown args; plural include_classifications
		// is an internal content-search flag, not a tool argument.
		const params = convertFiltersToApiParams({});
		expect(params.include_classification).toBe("summary");
		expect(params).not.toHaveProperty("include_classifications");
	});
});

