47	/** `{platform}:{team}:{channel}` — team-scoped so the same channel id in two
48	 *  Slack workspaces never collides. `team` is "" for platforms without one. */
49	function channelVisibilityKey(
50		platform: string,
51		teamId: string | null,
52		bareChannelId: string,
53	): string {
54		return `${platform.toLowerCase()}:${teamId ?? ""}:${bareChannelId}`;
55	}
56	
57	export interface ChannelVisibility {
58		/** Team-scoped keys the requester may read (per-agent fence ∩ per-user ACL). */
59		visibleKeys: Set<string>;
60		/** `{platform}:{channel}` → the team ids the AGENT is bound to it in. A
61		 *  channel bound in >1 team can't be disambiguated from a conversation id
62		 *  alone, so it fails closed. */
63		channelTeams: Map<string, Set<string>>;
64	}
65	
66	/**
67	 * Which channels may THIS requester read for THIS agent — the per-agent channel
68	 * fence (the agent's bound channels) INTERSECTED with the per-user channel ACL
69	 * gate ({@link filterChannelsForRequester}), team-scoped. A platform conversation
70	 * is visible iff {@link isConversationVisible}. Mirrors recall's gate so a user
71	 * never sees a channel transcript they're not a member of.
72	 */
73	export async function resolveChannelVisibility(
74		sql: DbClient,
75		args: {
76			organizationId: string;
77			agentId: string;
78			userId: string | null;
79			allowNotGraphed?: boolean;
80		},
81	): Promise<ChannelVisibility> {
82		const bound = await resolveBoundChannelRows(sql, {
83			organizationId: args.organizationId,
84			agentId: args.agentId,
85		});
86		const channelTeams = new Map<string, Set<string>>();
87		for (const c of bound) {
88			const bare = stripPlatformPrefix(c.platform, c.channel_id);
89			const pc = `${c.platform.toLowerCase()}:${bare}`;
90			const set = channelTeams.get(pc) ?? new Set<string>();
91			set.add(c.team_id ?? "");
92			channelTeams.set(pc, set);
93		}
94		const visible = await filterChannelsForRequester(sql, {
95			organizationId: args.organizationId,
96			userId: args.userId,
97			rows: bound,
98			allowNotGraphed: args.allowNotGraphed,
99		});
100		const visibleKeys = new Set(
101			visible.map((c) =>
102				channelVisibilityKey(
103					c.platform,
104					c.team_id,
105					stripPlatformPrefix(c.platform, c.channel_id),
106				),
107			),
108		);
109		return { visibleKeys, channelTeams };
110	}
111	
112	/** Can the requester read this platform conversation (`{platform}:{channel}:{thread}`)?
113	 *  Fail-closed: unbound, or a channel bound in ≥2 DISTINCT REAL workspaces (can't
114	 *  tie the conversation to a single team), is not visible.
115	 *
116	 *  A NULL/"" team is a WILDCARD ("workspace unknown yet" — a binding written
117	 *  before its workspace healed from the first inbound event), NOT a distinct
118	 *  workspace. `team_id` is now guaranteed to be a real workspace or NULL (never a
119	 *  Grid enterprise id), so the gate needs zero connector knowledge: it counts
120	 *  distinct non-null teams and only fails closed on genuine cross-workspace
121	 *  ambiguity (2+ real teams). One real team + any number of NULLs resolves to
122	 *  that team; all-NULL resolves via the wildcard visible key. */
123	export function isConversationVisible(
124		conversationId: string,
125		vis: ChannelVisibility,
126	): boolean {
127		const parts = conversationId.split(":");
128		const platform = (parts[0] ?? "").toLowerCase();
129		const channel = parts[1] ?? "";
130		const teams = vis.channelTeams.get(`${platform}:${channel}`);
131		if (!teams || teams.size === 0) return false; // unbound
132		const realTeams = [...teams].filter((t) => t !== "");
133		if (realTeams.length > 1) return false; // genuine cross-workspace ambiguity
134		// One real team (NULLs are wildcards that resolve to it), or all-NULL (a
135		// teamless/unknown-yet binding — resolves via the "" wildcard visible key).
136		const team = realTeams[0] ?? null;
137		return vis.visibleKeys.has(channelVisibilityKey(platform, team, channel));
138	}
