45	/**
46	 * Stamp `metadata.pending_proposal_count` onto every `change_set` content item,
47	 * counting the pending proposal runs still open for its window. The change_set
48	 * event is permanent, so its batch Approve/Reject buttons can't derive their
49	 * visibility from the event alone — a resolved window would keep showing live
50	 * buttons that error on click. One batched query over all present windows keeps
51	 * this off the per-item hot path; items with no window are left untouched.
52	 */
53	async function stampPendingProposalCounts(
54	  sql: ReturnType<typeof getDb>,
55	  organizationId: string,
56	  items: ContentItem[]
57	): Promise<void> {
58	  const windowIds = new Set<number>();
59	  for (const item of items) {
60	    if (item.semantic_type !== 'change_set') continue;
61	    const wid = (item.metadata as Record<string, unknown> | undefined)?.window_id;
62	    if (typeof wid === 'number') windowIds.add(wid);
63	  }
64	  if (windowIds.size === 0) return;
65	
66	  const rows = await sql<{ window_id: number; pending: number }>`
67	    SELECT window_id, COUNT(*)::int AS pending
68	    FROM runs
69	    WHERE organization_id = ${organizationId}
70	      AND run_type = 'internal'
71	      AND approval_status = 'pending'
72	      AND window_id = ANY(${pgBigintArray([...windowIds])}::bigint[])
73	    GROUP BY window_id
74	  `;
75	  const pendingByWindow = new Map<number, number>();
76	  for (const r of rows) pendingByWindow.set(Number(r.window_id), Number(r.pending));
77	
78	  for (const item of items) {
79	    if (item.semantic_type !== 'change_set') continue;
80	    const metadata = (item.metadata ?? {}) as Record<string, unknown>;
81	    const wid = metadata.window_id;
82	    if (typeof wid !== 'number') continue;
83	    item.metadata = {
84	      ...metadata,
85	      pending_proposal_count: pendingByWindow.get(wid) ?? 0,
86	    };
87	  }
88	}
