import { beforeAll, describe, expect, it } from 'vitest';
import { getContent } from '../../../tools/get_content';
import type { ToolContext } from '../../../tools/registry';
import { initWorkspaceProvider } from '../../../workspace';
import { cleanupTestDatabase, getTestDb } from '../../setup/test-db';
import {
  addUserToOrganization,
  createTestOrganization,
  createTestUser,
  seedSystemEntityTypes,
} from '../../setup/test-fixtures';

describe('probe: classification_filters end to end', () => {
  let ctx: ToolContext;
  let facetId: number;

  beforeAll(async () => {
    await initWorkspaceProvider();
    await cleanupTestDatabase();
    await seedSystemEntityTypes();
    const org = await createTestOrganization({ name: 'Probe Org' });
    const user = await createTestUser({ email: 'probe@example.com' });
    await addUserToOrganization(user.id, org.id, 'owner');

    const sql = getTestDb();
    const [ev] = await sql<{ id: number }[]>`
      INSERT INTO events (organization_id, origin_id, title, payload_type, payload_text,
                          semantic_type, occurred_at, created_at)
      VALUES (${org.id}, 'probe-1', 'probe row', 'text', 'probe row', 'audit', NOW(), NOW())
      RETURNING id
    `;
    const [f] = await sql<{ id: number }[]>`
      INSERT INTO classify_facet (organization_id, slug, name, attribute_key, status,
                                  created_by, entity_ids, attribute_values, min_similarity)
      VALUES (${org.id}, 'probe-kind', 'Probe kind', 'probe_kind', 'active', ${user.id},
              ARRAY[]::bigint[], ${sql.json({ alpha: { description: 'A', examples: [] } })}, 0.7)
      RETURNING id
    `;
    facetId = f.id;
    await sql`
      INSERT INTO event_classifications (event_id, classifier_id, watcher_id, window_id,
                                         "values", confidences, source, is_manual)
      VALUES (${ev.id}, ${f.id}, NULL, NULL, ${'{alpha}'}::text[],
              ${sql.json({ alpha: 1 })}, 'user', true)
    `;

    ctx = {
      organizationId: org.id,
      userId: user.id,
      memberRole: 'owner',
      isAuthenticated: true,
      tokenType: 'oauth',
      scopedToOrg: false,
      allowCrossOrg: true,
      scopes: ['mcp:read'],
    } as ToolContext;
  });

  it('resolves the classifier by slug', async () => {
    const sql = getTestDb();
    const rows = await sql`
      SELECT id, slug, watcher_id, organization_id FROM classify_facet WHERE id = ${facetId}
    `;
    console.log('FACET ROW:', JSON.stringify(rows));
    const globalMatch = await sql`
      SELECT ccl.slug, ccl.id FROM classify_facet ccl
      WHERE ccl.slug IN ('probe-kind') AND ccl.watcher_id IS NULL
    `;
    console.log('GLOBAL RESOLVE:', JSON.stringify(globalMatch));
    expect(globalMatch.length).toBeGreaterThan(0);
  });

  it('filters by classification', async () => {
    const result = await getContent(
      { classification_filters: { 'probe-kind': ['alpha'] }, limit: 100 } as never,
      {} as never,
      ctx
    );
    console.log('FILTER RESULT:', JSON.stringify(result.content.map((c) => c.title)));
    expect(result.content.length).toBe(1);
  });
});

