/**
 * Repro for #2214: `classification_filters` returns zero rows even though the
 * classifier resolves and the generated EXISTS predicate matches the row.
 *
 * Minimal fixture on purpose — no entity, no connection, no client_ids, no
 * score sort — so nothing but the classification path is under test.
 */

import { beforeAll, describe, expect, it } from 'vitest';
import { getContent } from '../../../tools/get_content';
import type { ToolContext } from '../../../tools/registry';
import { initWorkspaceProvider } from '../../../workspace';
import { cleanupTestDatabase, getTestDb } from '../../setup/test-db';
import {
  addUserToOrganization,
  createTestOrganization,
  createTestUser,
  seedSystemEntityTypes,
} from '../../setup/test-fixtures';

describe('#2214 classification_filters', () => {
  let ctx: ToolContext;
  let facetId: number;
  let eventId: number;

  beforeAll(async () => {
    await initWorkspaceProvider();
    await cleanupTestDatabase();
    await seedSystemEntityTypes();
    const org = await createTestOrganization({ name: 'Cls Repro Org' });
    const user = await createTestUser({ email: 'cls-repro@example.com' });
    await addUserToOrganization(user.id, org.id, 'owner');

    const sql = getTestDb();
    const [ev] = await sql<{ id: number }[]>`
      INSERT INTO events (organization_id, origin_id, title, payload_type, payload_text,
                          semantic_type, occurred_at, created_at)
      VALUES (${org.id}, 'cls-repro-1', 'classified row', 'text', 'classified row',
              'audit', NOW(), NOW())
      RETURNING id
    `;
    eventId = ev.id;

    await sql`
      INSERT INTO events (organization_id, origin_id, title, payload_type, payload_text,
                          semantic_type, occurred_at, created_at)
      VALUES (${org.id}, 'cls-repro-2', 'unclassified row', 'text', 'unclassified row',
              'audit', NOW(), NOW())
    `;

    const [f] = await sql<{ id: number }[]>`
      INSERT INTO classify_facet (organization_id, slug, name, attribute_key, status,
                                  created_by, entity_ids, attribute_values, min_similarity)
      VALUES (${org.id}, 'repro-kind', 'Repro kind', 'repro_kind', 'active', ${user.id},
              ARRAY[]::bigint[], ${sql.json({ alpha: { description: 'A', examples: [] } })}, 0.7)
      RETURNING id
    `;
    facetId = f.id;

    await sql`
      INSERT INTO event_classifications (event_id, classifier_id, watcher_id, window_id,
                                         "values", confidences, source, is_manual)
      VALUES (${ev.id}, ${f.id}, NULL, NULL, ${'{alpha}'}::text[],
              ${sql.json({ alpha: 1 })}, 'user', true)
    `;

    ctx = {
      organizationId: org.id,
      userId: user.id,
      memberRole: 'owner',
      isAuthenticated: true,
      tokenType: 'oauth',
      scopedToOrg: false,
      allowCrossOrg: true,
      scopes: ['mcp:read'],
    } as ToolContext;
  });

  it('preconditions: the classifier resolves and the predicate matches in SQL', async () => {
    const sql = getTestDb();
    const resolved = await sql`
      SELECT ccl.slug, ccl.id FROM classify_facet ccl
      WHERE ccl.slug IN ('repro-kind') AND ccl.watcher_id IS NULL
    `;
    expect(resolved.length).toBe(1);

    const matched = await sql`
      SELECT EXISTS (
        SELECT 1 FROM event_classifications cc
        WHERE cc.event_id = ${eventId}
          AND cc.classifier_id = ${facetId}
          AND cc."values" && ${'{alpha}'}::text[]
      ) AS ok
    `;
