} else if (organizationId) {
  // Use the SAME org-scope predicate as every other listing path
  // (buildOrgScopeWhere). This branch used to require `f.entity_ids` to
  // overlap an org entity, which silently dropped two whole classes of row:
  //   - events with NULL/empty entity_ids (audit rows, system events) —
  //     and because `&&` against NULL yields NULL, not false, they were
  //     dropped rather than evaluated
  //   - events reachable only via their connection's org
  // The effect was that an org-scoped event with no entity link was
  // invisible to classification_filters while visible to every other
  // filter. See #2214.
  const orgScope = buildOrgScopeWhere({
    organization_id: organizationId,
    baseParamIndex: baseParams.length + 1,
  });
  if (orgScope.sql) {
    // Drop the leading "AND " — baseConditions is joined with ' AND '.
    baseConditions.push(orgScope.sql.replace(/^AND\s+/, ''));
    baseParams.push(...orgScope.params);
  }
}

