import { createFileRoute, Link } from "@tanstack/react-router";
import { MonitorSmartphone } from "lucide-react";
import { useState } from "react";
import { DeviceConnect } from "@/components/devices/device-connect";
import {
  DeviceStatusDot,
  deviceName,
  inferredPlatform,
  PlatformIcon,
} from "@/components/devices/device-display";
import {
  InfraListSkeleton,
  InfraTabScaffold,
} from "@/components/infrastructure/infra-tab-scaffold";
import { useDevices } from "@/lib/api/connections";

export const Route = createFileRoute("/$owner/infrastructure/devices/")({
  component: DevicesTab,
});

/**
 * Devices tab: your paired Mac / Chrome extension / CLI as runtimes. Devices are
 * user-owned and private ("Yours") — they follow you across workspaces — so they
 * carry that badge even on this org-scoped page.
 */
function DevicesTab() {
  const { owner } = Route.useParams();
  const { data: devices = [], isLoading } = useDevices();
  const [adding, setAdding] = useState(false);

  return (
    <InfraTabScaffold
      lede="Your Mac, browser extension, or CLI — they run device-bound connectors and follow you across every workspace."
      addLabel="Add a device"
      adding={adding}
      onStartAdd={() => setAdding(true)}
      isLoading={isLoading}
      loadingSkeleton={<InfraListSkeleton />}
      isEmpty={devices.length === 0}
