import { TabEmptyState } from "@/components/entity-tabs/tab-states";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";

/** Shared list and add-form layout for the Connect infrastructure tabs. */
export function InfraTabScaffold({
	lede,
	addLabel,
	adding,
	onStartAdd,
	isLoading,
	loadingSkeleton,
	isEmpty,
	emptyIcon,
	emptyTitle,
	emptyDescription,
	banner,
	form,
	children,
}: {
	lede: string;
	/**
	 * Omit for resources you don't create from this page — an MCP client
	 * registers itself when a user connects the app, so there is nothing to add
	 * here and an "Add" affordance would be a dead end.
	 */
	addLabel?: string;
	adding: boolean;
	onStartAdd?: () => void;
	isLoading: boolean;
	loadingSkeleton: ReactNode;
	isEmpty: boolean;
	emptyIcon: LucideIcon;
	emptyTitle: string;
	emptyDescription: string;
	banner?: ReactNode;
	form?: ReactNode;
	children?: ReactNode;
}) {
	// Header Add only when the list already has items. An empty tab already
	// carries the primary CTA in TabEmptyState — doubling it in the lede row
	// is noise (Models/Sandboxes/Devices all share this scaffold).
	const canAdd = !!addLabel && !!onStartAdd;
