import { createFileRoute } from "@tanstack/react-router";
import { AppWindow } from "lucide-react";
import { useMemo, useState } from "react";
import {
	InfraListSkeleton,
	InfraTabScaffold,
} from "@/components/infrastructure/infra-tab-scaffold";
import { Button } from "@/components/ui/button";
import { useMembers } from "@/hooks/use-members";
import { useOrgContext } from "@/hooks/use-org-context";
import {
	type ConnectedClientItem,
	useConnectedClients,
	useRevokeMcpClient,
} from "@/lib/api/clients";

export const Route = createFileRoute("/$owner/infrastructure/clients")({
	component: ClientsTab,
});

export interface ClientGroup {
	key: string;
	title: string;
	clientIds: string[];
	connected: boolean;
	lastSeenAt: number | null;
	linkedUser: string | null;
	firstParty: boolean;
}

export function groupClients(clients: ConnectedClientItem[]): ClientGroup[] {
	const groups = new Map<string, ClientGroup>();

	for (const client of clients) {
		if (client.kind !== "mcp") continue;

		const title = client.title?.trim() || client.identifier || "Unknown app";
		const key = client.registrationGroupKey || client.id;

		const existing = groups.get(key);
		if (!existing) {
			groups.set(key, {
				key,
				title,
				clientIds: [client.id],
				connected: client.status === "connected",
				lastSeenAt: client.lastSeenAt ?? null,
				linkedUser: client.linkedUserName ?? client.linkedUserEmail ?? null,
				firstParty: !!client.firstParty,
			});
			continue;
		}

		existing.clientIds.push(client.id);
		existing.connected = existing.connected || client.status === "connected";
		existing.firstParty = existing.firstParty || !!client.firstParty;
		if ((client.lastSeenAt ?? 0) > (existing.lastSeenAt ?? 0)) {
			existing.lastSeenAt = client.lastSeenAt ?? null;
		}
	}

	return [...groups.values()].sort(
		(a, b) => (b.lastSeenAt ?? 0) - (a.lastSeenAt ?? 0),
	);
}

function relativeTime(ms: number | null): string {
	if (!ms) return "never";
	const diff = Date.now() - ms;
	if (diff < 60_000) return "just now";
	const mins = Math.floor(diff / 60_000);
	if (mins < 60) return `${mins}m ago`;
	const hours = Math.floor(mins / 60);
	if (hours < 24) return `${hours}h ago`;
	return `${Math.floor(hours / 24)}d ago`;
}

export function ClientsTab() {
	const { orgContext } = useOrgContext();
	const { isAdmin } = useMembers(orgContext.organizationId);
	const { data: clients = [], isLoading } = useConnectedClients(null, {
		refetchInterval: 60_000,
	});
	const revoke = useRevokeMcpClient();
	const [confirmingKey, setConfirmingKey] = useState<string | null>(null);
	const [pendingKey, setPendingKey] = useState<string | null>(null);

	const groups = useMemo(() => groupClients(clients), [clients]);

	return (
		<InfraTabScaffold
			lede="Apps connected to this workspace over MCP — ChatGPT, Claude, your CLI. They authenticate as a person and act with that person's access."
			adding={false}
			isLoading={isLoading}
			loadingSkeleton={<InfraListSkeleton />}
			isEmpty={groups.length === 0}
			emptyIcon={AppWindow}
			emptyTitle="No apps connected"
			emptyDescription="When someone connects an MCP client to this workspace, it shows up here."
		>
			{groups.map((group, idx) => (
				<div
					key={group.key}
					className={`flex items-center gap-3 px-3 py-2.5 ${
						idx === groups.length - 1 ? "" : "border-b"
					}`}
				>
					<AppWindow className="h-4 w-4 shrink-0 text-muted-foreground" />

					<div className="min-w-0 flex-1">
						<div className="flex items-center gap-2">
							<span className="truncate text-sm font-medium">
								{group.title}
							</span>
							{group.clientIds.length > 1 ? (
								<span className="shrink-0 rounded-md bg-muted px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground">
									{group.clientIds.length} registrations
								</span>
							) : null}
							{group.firstParty ? (
								<span className="shrink-0 rounded-md bg-muted px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
									Lobu
								</span>
							) : null}
						</div>
						<div className="truncate text-xs text-muted-foreground">
							{group.linkedUser ? `${group.linkedUser} · ` : ""}
							{group.connected
								? `active ${relativeTime(group.lastSeenAt)}`
								: "disconnected"}
						</div>
					</div>

					{isAdmin && group.connected ? (
						confirmingKey === group.key ? (
							<div className="flex shrink-0 items-center gap-1">
								<Button
									variant="destructive"
									size="sm"
									className="h-7 px-2 text-xs"
									disabled={revoke.isPending}
									onClick={() => {
										setPendingKey(group.key);
										revoke.mutate(
											{ clientId: group.clientIds[0], scope: "all" },
											{
												onSettled: () => {
													setPendingKey(null);
													setConfirmingKey(null);
												},
											},
										);
									}}
								>
									{revoke.isPending && pendingKey === group.key
										? "Revoking…"
										: "Confirm revoke"}
								</Button>
								<Button
									variant="ghost"
									size="sm"
									className="h-7 px-2 text-xs"
									disabled={revoke.isPending}
									onClick={() => setConfirmingKey(null)}
								>
									Cancel
								</Button>
							</div>
						) : (
							<Button
								variant="ghost"
								size="sm"
								className="h-7 shrink-0 text-xs text-muted-foreground hover:text-destructive"
								disabled={revoke.isPending}
								onClick={() => setConfirmingKey(group.key)}
							>
								Revoke
							</Button>
						)
					) : null}

					<span
						aria-label={group.connected ? "Connected" : "Disconnected"}
						className={`h-2 w-2 shrink-0 rounded-full ${
							group.connected ? "bg-emerald-500" : "bg-muted-foreground/40"
						}`}
					/>
				</div>
			))}
		</InfraTabScaffold>
	);
}

