it('keeps the persisted row in step with the live auth context', async () => {
  // The reuse path refreshes the row BEFORE re-resolving auth, then upgrades
  // `session.authCtx` in place (org, role, user/client binding). If the
  // post-upgrade write is missing, the row keeps the pre-upgrade binding and
  // another replica recovering this session enforces the stale identity.
  const { token } = await createTestAccessToken(user.id, org.id, client.client_id);
  const sessionId = await initSession({ token, orgSlug: org.slug });

  // Scramble the persisted binding, then make a normal request: the handler
  // must write the live context back over it.
  await getTestDb()`
    UPDATE mcp_sessions
    SET user_id = NULL, organization_id = NULL, is_authenticated = false
    WHERE session_id = ${sessionId}
  `;

  const res = await toolsList(sessionId, { token, orgSlug: org.slug });
  expect(res.status).toBe(200);

  const rows = await getTestDb()`
    SELECT user_id, organization_id, is_authenticated
    FROM mcp_sessions WHERE session_id = ${sessionId}
  `;
  expect(rows).toHaveLength(1);
  const row = rows[0] as {
    user_id: string | null;
    organization_id: string | null;
    is_authenticated: boolean;
  };
  expect(row.user_id).toBe(user.id);
  expect(row.organization_id).toBe(org.id);
  expect(row.is_authenticated).toBe(true);
});

