15	/**
16	 * Hash a client secret using scrypt (similar security to bcrypt)
17	 * Format: salt:hash (both hex encoded)
18	 */
19	export function hashClientSecret(secret: string): string {
20	  const salt = randomBytes(16);
21	  const hash = scryptSync(secret, salt, 64);
22	  return `${salt.toString('hex')}:${hash.toString('hex')}`;
23	}
