25	/**
26	 * Verify a client secret against a stored hash
27	 */
28	function verifyClientSecret(secret: string, storedHash: string): boolean {
29	  try {
30	    const [saltHex, hashHex] = storedHash.split(':');
31	    if (!saltHex || !hashHex) return false;
32	
33	    const salt = Buffer.from(saltHex, 'hex');
34	    const expectedHash = Buffer.from(hashHex, 'hex');
35	    const actualHash = scryptSync(secret, salt, 64);
36	
37	    return timingSafeEqual(expectedHash, actualHash);
38	  } catch {
39	    return false;
40	  }
41	}
