43	/**
44	 * OAuth Clients Store
45	 *
46	 * Handles dynamic client registration and client lookup.
47	 */
48	export class OAuthClientsStore {
49	  constructor(private sql: DbClient) {}
50	
51	  async touchClientActivity(params: {
52	    clientId: string;
53	    organizationId?: string | null;
54	    userId?: string | null;
55	    agentId?: string | null;
56	    userAgent?: string | null;
57	    clientInfo?: Record<string, unknown> | null;
58	    capabilities?: Record<string, unknown> | null;
59	  }): Promise<void> {
60	    const patch: Record<string, unknown> = {
61	      last_seen_at: Date.now(),
62	    };
63	
64	    if (params.agentId) patch.last_agent_id = params.agentId;
65	    if (params.userAgent) patch.last_user_agent = params.userAgent;
66	    if (params.clientInfo) patch.last_client_info = params.clientInfo;
67	    if (params.capabilities) patch.last_capabilities = params.capabilities;
68	
69	    await this.sql`
70	      UPDATE oauth_clients
71	      SET
72	        organization_id = COALESCE(organization_id, ${params.organizationId ?? null}),
73	        user_id = COALESCE(user_id, ${params.userId ?? null}),
74	        metadata = COALESCE(metadata, '{}'::jsonb) || ${this.sql.json(patch)}::jsonb,
75	        updated_at = NOW()
76	      WHERE id = ${params.clientId}
77	    `;
78	  }
