2	 * OAuth Clients Store
3	 *
4	 * Manages OAuth client registration and retrieval.
5	 * Implements RFC 7591 Dynamic Client Registration.
6	 */
7	
8	import { randomBytes, scryptSync, timingSafeEqual } from 'node:crypto';
9	import type { DbClient } from '../../db/client';
10	import { pgTextArray } from '../../db/client';
11	import { recordLifecycleEvent } from '../../utils/insert-event';
12	import type { OAuthClient, OAuthClientMetadata, StoredOAuthClient } from './types';
13	import { generateClientId, generateClientSecret } from './utils';
14	
15	/**
16	 * Hash a client secret using scrypt (similar security to bcrypt)
17	 * Format: salt:hash (both hex encoded)
18	 */
19	export function hashClientSecret(secret: string): string {
20	  const salt = randomBytes(16);
21	  const hash = scryptSync(secret, salt, 64);
22	  return `${salt.toString('hex')}:${hash.toString('hex')}`;
23	}
24	
25	/**
26	 * Verify a client secret against a stored hash
27	 */
28	function verifyClientSecret(secret: string, storedHash: string): boolean {
29	  try {
30	    const [saltHex, hashHex] = storedHash.split(':');
31	    if (!saltHex || !hashHex) return false;
32	
33	    const salt = Buffer.from(saltHex, 'hex');
34	    const expectedHash = Buffer.from(hashHex, 'hex');
35	    const actualHash = scryptSync(secret, salt, 64);
36	
37	    return timingSafeEqual(expectedHash, actualHash);
38	  } catch {
39	    return false;
40	  }
41	}
42	
43	/**
44	 * OAuth Clients Store
45	 *
46	 * Handles dynamic client registration and client lookup.
47	 */
48	export class OAuthClientsStore {
49	  constructor(private sql: DbClient) {}
50	
51	  async touchClientActivity(params: {
52	    clientId: string;
53	    organizationId?: string | null;
54	    userId?: string | null;
55	    agentId?: string | null;
56	    userAgent?: string | null;
57	    clientInfo?: Record<string, unknown> | null;
58	    capabilities?: Record<string, unknown> | null;
59	  }): Promise<void> {
60	    const patch: Record<string, unknown> = {
61	      last_seen_at: Date.now(),
62	    };
63	
64	    if (params.agentId) patch.last_agent_id = params.agentId;
65	    if (params.userAgent) patch.last_user_agent = params.userAgent;
66	    if (params.clientInfo) patch.last_client_info = params.clientInfo;
67	    if (params.capabilities) patch.last_capabilities = params.capabilities;
68	
69	    await this.sql`
70	      UPDATE oauth_clients
71	      SET
72	        organization_id = COALESCE(organization_id, ${params.organizationId ?? null}),
73	        user_id = COALESCE(user_id, ${params.userId ?? null}),
74	        metadata = COALESCE(metadata, '{}'::jsonb) || ${this.sql.json(patch)}::jsonb,
75	        updated_at = NOW()
76	      WHERE id = ${params.clientId}
77	    `;
78	  }
79	
80	  /**
81	   * Get a client by ID
82	   */
83	  async getClient(clientId: string): Promise<OAuthClient | null> {
84	    const result = await this.sql`
85	      SELECT * FROM oauth_clients WHERE id = ${clientId}
86	    `;
87	
88	    if (result.length === 0) return null;
89	
90	    const client = result[0] as StoredOAuthClient;
91	    return this.toOAuthClient(client);
92	  }
93	
94	  /**
95	   * Register a new client (RFC 7591)
96	   *
97	   * @param metadata - Client metadata from registration request
98	   * @param userId - Optional user ID if client is user-owned
99	   * @param organizationId - Optional organization ID for scoping
100	   * @returns Full client info including credentials (shown once)
101	   */
102	  async registerClient(
103	    metadata: OAuthClientMetadata,
104	    userId?: string,
105	    organizationId?: string,
106	    extraMetadata?: Record<string, unknown>
107	  ): Promise<OAuthClient> {
108	    const clientId = generateClientId();
109	    const clientSecret = generateClientSecret();
110	
111	    // Hash the client secret for storage
112	    const clientSecretHash = hashClientSecret(clientSecret);
113	
114	    // Client secret expires in 1 year
115	    const clientSecretExpiresAt = new Date(Date.now() + 365 * 24 * 3600 * 1000);
116	
117	    await this.sql`
118	      INSERT INTO oauth_clients (
119	        id,
120	        client_secret,
121	        client_secret_expires_at,
122	        redirect_uris,
123	        token_endpoint_auth_method,
124	        grant_types,
125	        response_types,
126	        client_name,
127	        client_uri,
128	        logo_uri,
129	        scope,
130	        contacts,
131	        tos_uri,
132	        policy_uri,
133	        software_id,
134	        software_version,
135	        user_id,
136	        organization_id,
137	        metadata
138	      ) VALUES (
139	        ${clientId},
140	        ${clientSecretHash},
141	        ${clientSecretExpiresAt},
142	        ${pgTextArray(metadata.redirect_uris)}::text[],
143	        ${metadata.token_endpoint_auth_method || 'none'},
144	        ${pgTextArray(metadata.grant_types || ['authorization_code', 'refresh_token'])}::text[],
145	        ${pgTextArray(metadata.response_types || ['code'])}::text[],
146	        ${metadata.client_name || null},
147	        ${metadata.client_uri || null},
148	        ${metadata.logo_uri || null},
149	        ${metadata.scope || null},
150	        ${metadata.contacts ? pgTextArray(metadata.contacts) : null}::text[],
151	        ${metadata.tos_uri || null},
152	        ${metadata.policy_uri || null},
153	        ${metadata.software_id || null},
154	        ${metadata.software_version || null},
155	        ${userId || null},
156	        ${organizationId || null},
157	        ${this.sql.json(extraMetadata || {})}
158	      )
159	    `;
160	
161	    if (organizationId) {
162	      recordLifecycleEvent({
163	        organizationId,
164	        entityType: 'client',
165	        op: 'created',
166	        entityId: clientId,
167	        summary: `Connected app "${metadata.client_name || clientId}" registered`,
168	        extra: { user_id: userId ?? null },
169	      });
170	    }
171	
172	    return {
173	      ...metadata,
174	      client_id: clientId,
175	      client_secret: clientSecret, // Return plaintext, shown only during registration
176	      client_id_issued_at: Math.floor(Date.now() / 1000),
177	      client_secret_expires_at: Math.floor(clientSecretExpiresAt.getTime() / 1000),
178	    };
179	  }
180	
181	  /**
182	   * Verify client credentials
183	   *
184	   * @param clientId - Client ID
185	   * @param clientSecret - Client secret to verify
186	   * @returns True if credentials are valid
187	   */
188	  async verifyClientCredentials(clientId: string, clientSecret: string): Promise<boolean> {
189	    const result = await this.sql`
190	      SELECT client_secret, client_secret_expires_at
191	      FROM oauth_clients
192	      WHERE id = ${clientId}
193	    `;
194	
195	    if (result.length === 0) return false;
196	
197	    const client = result[0] as Pick<
198	      StoredOAuthClient,
199	      'client_secret' | 'client_secret_expires_at'
200	    >;
201	
202	    // Check if secret has expired
203	    if (client.client_secret_expires_at && new Date(client.client_secret_expires_at) < new Date()) {
