205	    }
206	
207	    // Public clients (no secret)
208	    if (!client.client_secret) {
209	      return clientSecret === undefined || clientSecret === '';
210	    }
211	
212	    // Verify the secret
213	    return verifyClientSecret(clientSecret, client.client_secret);
214	  }
215	
