38	 * signal for first-party clients. (Keep in sync with the CLI / bridge clients.)
39	 */
40	const LOBU_FIRST_PARTY_SOFTWARE_IDS = new Set([
41		"lobu-cli",
42		"lobu",
43		"lobu-mac-bridge",
44		"lobu-ios-bridge",
45		"lobu-bridge",
46	]);
