import { createContext, type ReactNode, useContext } from "react";
import {
	type ConnectionConnectorGroup,
	useConnectionConnectorGroups,
} from "@/lib/api/connections";

type MemoryConnectorGroupsValue = {
	groups: ConnectionConnectorGroup[];
	isLoading: boolean;
};

const MemoryConnectorGroupsContext =
	createContext<MemoryConnectorGroupsValue | null>(null);

export function MemoryConnectorGroupsProvider({
	organizationId,
	isWorkspaceLoading,
	children,
}: {
	organizationId: string | null;
	isWorkspaceLoading?: boolean;
	children: ReactNode;
}) {
	const { data: groups = [], isLoading: isGroupsLoading } =
		useConnectionConnectorGroups(organizationId);

	return (
		<MemoryConnectorGroupsContext.Provider
			value={{
				groups,
				isLoading: !!isWorkspaceLoading || isGroupsLoading,
			}}
		>
			{children}
		</MemoryConnectorGroupsContext.Provider>
	);
}

export function useMemoryConnectorGroups(): MemoryConnectorGroupsValue {
	const value = useContext(MemoryConnectorGroupsContext);
	if (!value) {
		throw new Error(
			"useMemoryConnectorGroups must be used within MemoryConnectorGroupsProvider",
		);
	}
	return value;
}

export function useOptionalMemoryConnectorGroups(): MemoryConnectorGroupsValue | null {
	return useContext(MemoryConnectorGroupsContext);
}
