147								label: scopeType?.name ?? decodeEntityTypeParam(scopedEntityType),
148								search: entityClearSearch,
149							}
150						: undefined
151				}
152				label={entity?.name ?? entityScope.split("/").slice(-1)[0]}
153				ownerSlug={ownerSlug}
