import { Link, useNavigate } from "@tanstack/react-router";
import { Boxes, ChevronRight, X } from "lucide-react";
import type { ReactNode } from "react";
import { EntityTypeGraphView } from "@/components/entities/entity-type-graph-view";
import { EntityTypeListPanel } from "@/components/entities/entity-type-list-panel";
import { EventsTab } from "@/components/entity-tabs/events-tab";
import { TabEmptyState } from "@/components/entity-tabs/tab-states";
import { EntityTypePage } from "@/components/settings/entity-types/entity-type-page";
import { Button } from "@/components/ui/button";
import { EntityIcon } from "@/components/ui/entity-icon";
import { useOrgContext } from "@/hooks/use-org-context";
import { useAgentWatchersList } from "@/hooks/use-watchers";
import { useAgents, useEntityType, useResolvedPath } from "@/lib/api";
import { useSchedules } from "@/lib/api/schedules";
import { type MemoryView, memoryBrowseTypeSearch } from "@/lib/memory-browse";
import { pruneSearch } from "@/lib/router-search";
import { decodeEntityBrowsePath, decodeEntityTypeParam } from "@/lib/url";
import { MemberScopeGate } from "./member-scope-gate";
import { MemoryEntityDetail } from "./memory-entity-detail";

/**
 * Memory content pane: Events (Activity in the sidebar) or entity types/records
 * (Context in the sidebar). View is driven by the URL only — the Events/Entities
 * header tab strip is gone; the sidebar is the switch.
 */
export function MemoryHomePane({
	organizationId,
	ownerSlug,
	typeScope,
	entityScope,
	agentScope,
	watcherScope,
	scheduleScope,
	view,
	create,
	createType = false,
}: {
	organizationId: string | null;
	ownerSlug: string;
	typeScope?: string;
	entityScope?: string;
	agentScope?: string;
	watcherScope?: string;
	scheduleScope?: string;
	view: MemoryView;
	create: boolean;
	/** Context (entities) subpage: create entity type. */
	createType?: boolean;
}) {
	const navigate = useNavigate();
	const { orgContext } = useOrgContext();
	const { data: agents = [] } = useAgents();
	const agentLabel = agentScope
		? (agents.find((agent) => agent.agentId === agentScope)?.name ?? agentScope)
		: undefined;
	const { data: agentWatchers = [] } = useAgentWatchersList(agentScope, {
		includeDetails: false,
	});
	const watcherLabel = watcherScope
		? (agentWatchers.find((w) => w.behavior_id === watcherScope)?.name ??
			`Behavior ${watcherScope}`)
		: undefined;
	const { data: agentSchedules = [] } = useSchedules(agentScope);
	const scheduleLabel = scheduleScope
		? (agentSchedules.find((s) => s.id === scheduleScope)?.description ??
			"Schedule")
		: undefined;
	const typeSlug = typeScope ? decodeEntityTypeParam(typeScope) : undefined;
	const isMemberScope =
		typeSlug === "$member" || entityScope?.split("/")[0] === "$member";

	// Resolve the selected entity (if any) to its id + type, for the events/feeds
	// filters and the detail render.
	const {
		data: resolved,
		isLoading: entityLoading,
		error: entityError,
	} = useResolvedPath(
		entityScope ? `/${ownerSlug}/${decodeEntityBrowsePath(entityScope)}` : "",
		orgContext,
	);
	const entity = entityScope ? resolved?.entity : undefined;
	// The `?entity=` scope points at nothing (deleted / bad slug): the resolve
	// settled with no entity and no in-flight fetch.
	const entityNotFound =
		entityScope != null &&
		!entityLoading &&
		(entityError != null || resolved?.entity == null);
	// The type whose icon labels the scope header — the scoped type, or the
	// selected entity's own type when an entity is scoped.
	const { data: scopeType } = useEntityType(
		entity?.entity_type ?? typeSlug ?? "",
		orgContext,
	);

	const closeCreateType = () => {
		void navigate({
			to: "/$owner/memory",
			params: { owner: ownerSlug },
			search: { view: "entities" },
		});
	};

	// Clear steps ONE level up the scope hierarchy (entity → its type list →
	// nothing), it doesn't nuke everything. `view` is always emitted explicitly:
	// once a scope is gone, resolveMemoryView() no longer infers "entities" from
	// an entity-shaped scope and would fall back to "events" — an omitted view
	// would bounce a cleared Context scope over to Activity (events).
	//
	// A single entity's type: from the resolved entity, or parsed from the
	// `<type>/<slug>` scope string as a fallback before it resolves. The `type`
	// search param is read back through decodeEntityTypeParam, so encode the
	// leading `$` (e.g. `$member`) to stay symmetric.
	const scopedEntityType =
		entity?.entity_type ??
		(entityScope
			? decodeEntityTypeParam(entityScope.split("/")[0] ?? "")
			: undefined);
	// Clearing a single entity drops back to that type's LIST (so you keep
	// browsing the type), not out to "choose a type".
	const entityClearSearch: Record<string, string | undefined> = scopedEntityType
		? { view, type: scopedEntityType }
		: { view };
	const agentClearSearch: Record<string, string | undefined> = { view };
	const watcherClearSearch: Record<string, string | undefined> = agentScope
		? { view, agent: agentScope }
		: { view };
	const scheduleClearSearch: Record<string, string | undefined> = agentScope
		? { view, agent: agentScope }
		: { view };

	// Drill breadcrumb for entity / behavior / schedule detail only. Events
	// filters live in MemoryScopeBar (Events view), not here.
	const scopeHeader = entityScope ? (
		<ScopeHeader
			icon={
				entity?.entity_type ? (
					<EntityIcon icon={scopeType?.icon} className="h-4 w-4 shrink-0" />
				) : null
			}
			// The entity's type, shown as a clickable crumb before the name:
			// `Task › <name>`. Clicking it drops to that type's list (same target
			// as Clear on a single entity), so the type is always one hop away.
			typeSegment={
				scopedEntityType
					? {
							label: scopeType?.name ?? decodeEntityTypeParam(scopedEntityType),
							search: entityClearSearch,
						}
					: undefined
			}
			label={entity?.name ?? entityScope.split("/").slice(-1)[0]}
			ownerSlug={ownerSlug}
			clearSearch={entityClearSearch}
		/>
	) : watcherScope && agentScope ? (
		<ScopeHeader
			typeSegment={{
				label: agentLabel ?? "Agent",
				search: agentClearSearch,
			}}
			label={watcherLabel ?? "Behavior"}
			ownerSlug={ownerSlug}
			clearSearch={watcherClearSearch}
		/>
	) : scheduleScope && agentScope ? (
		<ScopeHeader
			typeSegment={{
				label: agentLabel ?? "Agent",
				search: agentClearSearch,
			}}
			label={scheduleLabel ?? "Schedule"}
			ownerSlug={ownerSlug}
			clearSearch={scheduleClearSearch}
		/>
	) : null;

	const handleCreateChange = (open: boolean) => {
		if (!typeSlug) return;
		const link = memoryBrowseTypeSearch(ownerSlug, typeSlug, { view });
		// `memoryBrowseTypeSearch` clears stale `?entity=` / connector scopes.
		void navigate({
			to: link.to,
			params: link.params,
			search: pruneSearch({
				...link.search,
				create: open ? "true" : undefined,
			}) as Record<string, string | undefined>,
			replace: true,
		});
	};

	const paneBody = (
		<>
			{entityNotFound ? (
				<TabEmptyState
					icon={Boxes}
					title="Entity not found"
					description="This entity no longer exists. Clear the selection to keep browsing."
				/>
			) : null}

			{!entityNotFound && view === "events" ? (
				<EventsTab
					organizationId={organizationId}
					ownerSlug={ownerSlug}
					hideSourceFilter
					entityId={entity?.id}
					scopedEntityTypes={!entityScope && typeSlug ? [typeSlug] : undefined}
				/>
			) : null}

			{!entityNotFound && view === "entities" ? (
				createType ? (
					// Centered reading column (same as Connect / agent pages).
					<div className="mx-auto w-full max-w-3xl">
						<EntityTypePage
							entityType={null}
							orgContext={orgContext}
							onClose={closeCreateType}
						/>
					</div>
				) : entityScope ? (
					<MemoryEntityDetail ownerSlug={ownerSlug} browsePath={entityScope} />
				) : typeSlug ? (
					<EntityTypeListPanel
						ownerSlug={ownerSlug}
						entityTypeSlug={typeSlug}
						create={create}
						onCreateChange={handleCreateChange}
					/>
				) : (
					// Scope bar is Events-only — Entities picks a type off the schema map.
					<EntityTypeGraphView ownerSlug={ownerSlug} />
				)
			) : null}
		</>
	);

	return (
		<div className="flex min-h-0 min-w-0 flex-1 flex-col gap-4">
			{/* Scope drill-down only — view switch lives in the sidebar
			    (Activity = events, Context = entities). */}
			{scopeHeader ? (
				<div className="sticky top-0 z-20 flex min-w-0 flex-col gap-3 bg-background pt-1">
					{scopeHeader}
				</div>
			) : null}

			{isMemberScope ? (
				<MemberScopeGate ownerSlug={ownerSlug} entityScope={entityScope}>
					{paneBody}
				</MemberScopeGate>
			) : (
				paneBody
			)}
		</div>
	);
}

/** A drill-down breadcrumb with a Clear button. */
function ScopeHeader({
	icon,
	typeSegment,
	label,
	ownerSlug,
	clearSearch,
}: {
	icon?: ReactNode;
	/**
	 * Optional breadcrumb crumb rendered before `label` as `<type> › <label>`.
	 * The crumb links to `search` (the type's list) so a selected entity always
	 * shows — and can navigate back to — its type.
	 */
	typeSegment?: { label: string; search: Record<string, string | undefined> };
	label: string;
	ownerSlug: string;
	clearSearch: Record<string, string | undefined>;
}) {
	return (
		<div className="flex min-w-0 items-center gap-1.5 border-l border-border/60 pb-1 pl-3 text-sm">
			{icon}
			{typeSegment ? (
				<>
					<Link
						to="/$owner/memory"
						params={{ owner: ownerSlug }}
						search={typeSegment.search}
						className="shrink-0 font-medium text-muted-foreground transition-colors hover:text-foreground hover:underline"
					>
						{typeSegment.label}
					</Link>
					<ChevronRight className="h-3.5 w-3.5 shrink-0 text-muted-foreground/60" />
				</>
			) : null}
			<span className="min-w-0 truncate font-medium text-foreground">
				{label}
			</span>
			<Button asChild variant="ghost" size="sm" className="h-6 gap-1 px-2">
				<Link
					to="/$owner/memory"
					params={{ owner: ownerSlug }}
					search={clearSearch}
				>
					<X className="h-3.5 w-3.5" />
					Clear
				</Link>
			</Button>
		</div>
	);
}

