1	import { createFileRoute, redirect } from "@tanstack/react-router";
2	import { MemoryConnectorGroupsProvider } from "@/components/memory/memory-connector-groups";
3	import { MemoryHomePane } from "@/components/memory/memory-home-pane";
4	import { OwnerWorkspaceGate } from "@/components/owner-workspace-gate";
5	import { useWorkspaceRoot } from "@/lib/api";
6	import {
7		memorySearchNeedsCanonicalRedirect,
8		parseAgentScope,
9		parseEntityScope,
10		parseScheduleScope,
11		parseWatcherScope,
12		resolveMemoryView,
13	} from "@/lib/memory-browse";
14	import { pruneSearch } from "@/lib/router-search";
15	import { decodeEntityTypeParam } from "@/lib/url";
16	
17	export const Route = createFileRoute("/$owner/memory/")({
18		loader: ({ context: { queryClient }, params }) => {
19			void queryClient.prefetchQuery(
20				useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
21			);
22		},
23		// Migrate legacy browsing to the current model: a `?browse_path` (an entity
24		// detail) becomes the `/memory/<type>/<slug>` path; a bare `?browse_type`
25		// becomes the in-place `?type=<slug>` scope. Temporary — drop after a release.
26		beforeLoad: ({ params, search }) => {
27			const s = search as Record<string, unknown>;
28			const legacyDetail =
29				typeof s.browse_path === "string" && s.browse_path.trim()
30					? s.browse_path.trim()
31					: undefined;
32			if (legacyDetail) {
33				throw redirect({
34					to: "/$owner/memory/$",
35					params: { owner: params.owner, _splat: legacyDetail },
36					search: {},
37					replace: true,
38				});
39			}
40			const legacyType =
41				typeof s.browse_type === "string" && s.browse_type.trim()
42					? s.browse_type.trim()
43					: undefined;
44			if (legacyType) {
45				throw redirect({
46					to: "/$owner/memory",
47					params: { owner: params.owner },
48					search: pruneSearch({
49						type: decodeEntityTypeParam(legacyType),
50						view: s.browse_view === "events" ? "events" : undefined,
51						create: s.create === true || s.create === "true" ? true : undefined,
52					}) as Record<string, string | undefined>,
53					replace: true,
54				});
55			}
56			// Memory Feeds tab removed — old ?view=feeds deep links land on Events.
57			if (s.view === "feeds") {
58				throw redirect({
59					to: "/$owner/memory",
60					params: { owner: params.owner },
61					search: pruneSearch({
62						...s,
63						view: "events",
64					}) as Record<string, string | undefined>,
65					replace: true,
66				});
67			}
68			const canonical = memorySearchNeedsCanonicalRedirect(s);
69			if (canonical) {
70				throw redirect({
71					to: "/$owner/memory",
72					params: { owner: params.owner },
73					search: canonical,
74					replace: true,
75				});
76			}
77		},
78		component: MemoryPage,
79		validateSearch: (search: Record<string, unknown>) => {
80			const result = pruneSearch(search) as Record<string, string | undefined>;
81			// `stringifyRouterSearch` JSON-parses primitive search values, so `?create=true`
82			// round-trips as boolean `true` — normalize back to the string the UI reads.
83			if (search.create === true || search.create === "true") {
84				result.create = "true";
85			}
86			// Create-entity-type subpage under the Context destination.
87			if (search.create_type === true || search.create_type === "true") {
88				result.create_type = "true";
89			}
90			return result;
91		},
92	});
93	
94	function MemoryPage() {
95		const { owner } = Route.useParams();
96		const search = Route.useSearch();
97		const typeScope =
98			typeof search.type === "string" && search.type.trim()
99				? decodeEntityTypeParam(search.type.trim())
100				: undefined;
101		const entityScope = parseEntityScope(search);
102		const agentScope = parseAgentScope(search);
103		const watcherScope = parseWatcherScope(search);
104		const scheduleScope = parseScheduleScope(search);
105		const createType = search.create_type === "true";
106		// Creating a type is always an Entities subpage.
107		const view = createType
108			? "entities"
109			: resolveMemoryView(
110					search.view,
111					typeScope != null || entityScope != null,
112				);
113		const create = search.create === "true";
114	
115		return (
116			<div className="flex flex-1 flex-col gap-6 px-4 py-6 lg:px-6">
117				<OwnerWorkspaceGate owner={owner}>
118					{(props) => (
119						<MemoryConnectorGroupsProvider
120							organizationId={props.organizationId}
121							isWorkspaceLoading={props.isWorkspaceLoading}
122						>
123							<div className="flex min-h-0 min-w-0 flex-1 flex-col">
124								<MemoryHomePane
125									organizationId={props.organizationId}
126									ownerSlug={props.ownerSlug}
127									typeScope={typeScope}
128									entityScope={entityScope}
129									agentScope={agentScope}
130									watcherScope={watcherScope}
131									scheduleScope={scheduleScope}
132									view={view}
133									create={create}
134									createType={createType}
135								/>
136							</div>
137						</MemoryConnectorGroupsProvider>
138					)}
139				</OwnerWorkspaceGate>
140			</div>
141		);
142	}
