	resolveMemoryView,
} from "@/lib/memory-browse";
import { pruneSearch } from "@/lib/router-search";
import { decodeEntityTypeParam } from "@/lib/url";

export const Route = createFileRoute("/$owner/memory/")({
	loader: ({ context: { queryClient }, params }) => {
		void queryClient.prefetchQuery(
			useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
		);
	},
	// Migrate legacy browsing to the current model: a `?browse_path` (an entity
	// detail) becomes the `/memory/<type>/<slug>` path; a bare `?browse_type`
	// becomes the in-place `?type=<slug>` scope. Temporary — drop after a release.
	beforeLoad: ({ params, search }) => {
		const s = search as Record<string, unknown>;
		const legacyDetail =
			typeof s.browse_path === "string" && s.browse_path.trim()
				? s.browse_path.trim()
				: undefined;
		if (legacyDetail) {
			throw redirect({
				to: "/$owner/memory/$",
				params: { owner: params.owner, _splat: legacyDetail },
				search: {},
				replace: true,
			});
		}
		const legacyType =
			typeof s.browse_type === "string" && s.browse_type.trim()
				? s.browse_type.trim()
				: undefined;
		if (legacyType) {
			throw redirect({
				to: "/$owner/memory",
				params: { owner: params.owner },
				search: pruneSearch({
					type: decodeEntityTypeParam(legacyType),
					view: s.browse_view === "events" ? "events" : undefined,
					create: s.create === true || s.create === "true" ? true : undefined,
				}) as Record<string, string | undefined>,
				replace: true,
			});
		}
		// Memory Feeds tab removed — old ?view=feeds deep links land on Events.
		if (s.view === "feeds") {
			throw redirect({
				to: "/$owner/memory",
				params: { owner: params.owner },
				search: pruneSearch({
					...s,
					view: "events",
				}) as Record<string, string | undefined>,
				replace: true,
			});
		}
		const canonical = memorySearchNeedsCanonicalRedirect(s);
		if (canonical) {
			throw redirect({
				to: "/$owner/memory",
				params: { owner: params.owner },
				search: canonical,
				replace: true,
			});
		}
	},
	component: MemoryPage,
	validateSearch: (search: Record<string, unknown>) => {
		const result = pruneSearch(search) as Record<string, string | undefined>;
		// `stringifyRouterSearch` JSON-parses primitive search values, so `?create=true`
		// round-trips as boolean `true` — normalize back to the string the UI reads.
		if (search.create === true || search.create === "true") {
			result.create = "true";
		}
		// Create-entity-type subpage under the Context destination.
		if (search.create_type === true || search.create_type === "true") {
			result.create_type = "true";
		}
		return result;
	},
});

function MemoryPage() {
	const { owner } = Route.useParams();
	const search = Route.useSearch();
	const typeScope =
		typeof search.type === "string" && search.type.trim()
			? decodeEntityTypeParam(search.type.trim())
			: undefined;
	const entityScope = parseEntityScope(search);
	const agentScope = parseAgentScope(search);
	const watcherScope = parseWatcherScope(search);
	const scheduleScope = parseScheduleScope(search);
	const createType = search.create_type === "true";
	// Creating a type is always an Entities subpage.
	const view = createType
		? "entities"
		: resolveMemoryView(
				search.view,
				typeScope != null || entityScope != null,
			);
	const create = search.create === "true";

	return (
		<div className="flex flex-1 flex-col gap-6 px-4 py-6 lg:px-6">
			<OwnerWorkspaceGate owner={owner}>
				{(props) => (
					<MemoryConnectorGroupsProvider
						organizationId={props.organizationId}
						isWorkspaceLoading={props.isWorkspaceLoading}
					>
						<div className="flex min-h-0 min-w-0 flex-1 flex-col">
							<MemoryHomePane
								organizationId={props.organizationId}
								ownerSlug={props.ownerSlug}
								typeScope={typeScope}
								entityScope={entityScope}
								agentScope={agentScope}
								watcherScope={watcherScope}
								scheduleScope={scheduleScope}
								view={view}
								create={create}
								createType={createType}
							/>
						</div>
					</MemoryConnectorGroupsProvider>
				)}
			</OwnerWorkspaceGate>
		</div>
	);
}

import { Activity, Boxes, type LucideIcon, Plug } from "lucide-react";

/**
 * Owner-scoped nav sections — one icon + label shared by sidebar and page
 * headers. The sidebar is the site map: sections render in this order.
 *
 * Memory is two destinations, not one page with tabs:
 *  - **Activity** → Events stream (`/memory`, default view)
 *  - **Context** → entity types/records (`/memory?view=entities`)
 * The Events/Entities tab strip on the Memory page is gone — the sidebar is
 * the switch. Connect is connectors + synthesized providers/sandboxes.
 */
export const OWNER_SECTIONS = {
	activity: {
		icon: Activity,
		label: "Activity",
		/** Router template. */
		to: "/$owner/memory",
		/**
		 * Events is the default Memory view — omit `view` so the URL stays clean.
		 * Active when the user is on `/memory` without an entities view/scope.
		 */
		search: {} as Record<string, unknown>,
		/** Path segment under `/$owner/` used for coarse matching. */
		segment: "memory",
		/** Which Memory view this row represents. */
		memoryView: "events" as const,
	},
	connectors: {
		icon: Plug,
		label: "Connect",
		to: "/$owner/connectors",
		search: {} as Record<string, unknown>,
		segment: "connectors",
		memoryView: null,
	},
	context: {
		icon: Boxes,
		label: "Context",
		to: "/$owner/memory",
		search: { view: "entities" } as Record<string, unknown>,
		segment: "memory",
		memoryView: "entities" as const,
	},
} as const satisfies Record<
	string,
	{
		icon: LucideIcon;
		label: string;
		to: string;
		search: Record<string, unknown>;
		segment: string;
		memoryView: "events" | "entities" | null;
	}
>;

export type OwnerSectionKey = keyof typeof OWNER_SECTIONS;

/**
 * Whether a sidebar section is active for the current path + search.
 * Activity and Context share `/memory`; the active one is decided by the
 * Memory view (and by entity-shaped scopes / splat paths for Context).
 */
export function isOwnerSectionActive(
	key: OwnerSectionKey,
	owner: string,
	pathname: string,
	search: Record<string, unknown>,
): boolean {
	const section = OWNER_SECTIONS[key];
	const base = `/${owner}/${section.segment}`;
	const onSegment =
		pathname === base ||
		pathname === `${base}/` ||
		pathname.startsWith(`${base}/`);

	if (!onSegment) return false;

	if (section.memoryView == null) {
		// Connect (and any future non-memory section): any path under the segment.
		return true;
	}

	// Entity detail / type splat under /memory/* is always the Context surface.
	const isSplat = pathname !== base && pathname !== `${base}/`;
	if (isSplat) return section.memoryView === "entities";

	const view = search.view;
	const hasEntityScope =
		typeof search.type === "string" ||
		typeof search.entity === "string" ||
		search.create_type === true ||
		search.create_type === "true";

	// Mirror resolveMemoryView: explicit view wins; type/entity scope implies
	// entities; bare /memory is events.
	const resolved: "events" | "entities" =
		view === "entities"
			? "entities"
			: view === "events" || view === "feeds"
				? "events"
				: hasEntityScope
					? "entities"
					: "events";

	return section.memoryView === resolved;
}

