1	import { pickPeekSearch } from "@/lib/peek-search";
2	import { pruneSearch } from "@/lib/router-search";
3	import {
4		decodeEntityBrowsePath,
5		decodeEntityTypeParam,
6		type EntityPathSegment,
7	} from "@/lib/url";
8	
9	/**
10	 * Selected vs. idle row treatment for the nested memory entity-type rail.
11	 * Selected uses a quiet fill and bottom accent rather than a full primary ring.
12	 * The transparent idle border keeps row height stable.
13	 */
14	export const MEMORY_RAIL_ROW_ACTIVE =
15		"bg-muted/50 text-foreground border-b-2 border-primary rounded-b-none";
16	export const MEMORY_RAIL_ROW_IDLE =
17		"border-b-2 border-transparent text-muted-foreground hover:bg-accent/50 hover:text-foreground";
18	
19	/**
20	 * The Memory view selected by `?view=`. Events (data stream + scope filters)
21	 * and Entities (types → records). Feed management lives on Connect; legacy
22	 * `?view=feeds` is treated as Events.
23	 */
24	export type MemoryView = "entities" | "events";
25	
26	/** Parse an explicit `?view=`, or null when unset (the caller picks a default). */
27	export function parseMemoryView(value: unknown): MemoryView | null {
28		if (value === "events") return "events";
29		// Removed Memory Feeds tab — old deep links land on Events.
30		if (value === "feeds") return "events";
31		if (value === "entities") return "entities";
32		return null;
33	}
34	
35	/**
36	 * The active view given the URL `?view=` and whether a type/entity is scoped.
37	 * Default: a type or entity scope lands on Entities (its list / its record); the
38	 * unscoped home lands on Events.
39	 */
40	export function resolveMemoryView(
41		value: unknown,
42		hasEntityShapedScope: boolean,
43	): MemoryView {
44		return parseMemoryView(value) ?? (hasEntityShapedScope ? "entities" : "events");
45	}
46	
47	/** Format entity path segments as `type/slug/…` for the `?entity=` scope. */
48	export function entityPathToBrowsePath(segments: EntityPathSegment[]): string {
49		return segments
50			.map((segment) => `${segment.entity_type}/${segment.slug}`)
51			.join("/");
52	}
53	
54	/**
55	 * The parsed shape of a `/memory/$` splat: the entity type slug (first segment)
56	 * and, for entity detail, the full path. A bare `/memory` (no splat) parses to
57	 * `{ typeSlug: undefined }` — the events home.
58	 */
59	export type MemorySplat = {
60		/** Raw (still URL-encoded) first path segment — the entity type. */
61		typeSegment?: string;
62		/** Full path after `/memory/` — `type` or `type/slug/...`. */
63		path?: string;
64		/** True when the splat addresses a single entity (has a slug after the type). */
65		isEntityDetail: boolean;
66	};
67	
68	export function parseMemorySplat(splat: string | undefined): MemorySplat {
69		const trimmed = (splat ?? "").replace(/^\/+|\/+$/g, "");
70		if (!trimmed) return { isEntityDetail: false };
71		const segments = trimmed.split("/");
72		return {
73			typeSegment: segments[0],
74			path: trimmed,
75			isEntityDetail: segments.length > 1,
76		};
77	}
78	
79	/**
80	 * A single-scope Memory selection. These variants are mutually exclusive.
81	 */
82	export type MemoryScope =
83		| { kind: "type"; slug: string }
84		| { kind: "connection"; ids: string }
85		| { kind: "agent"; id: string }
86		| { kind: "entity"; path: string };
87	
88	/**
89	 * Set one in-place scope on `/memory`, clear the other scopes, and preserve the
90	 * current view. `viewOverride` handles scopes that the current view cannot show.
91	 */
92	export function memoryScopeSearch(
93		ownerSlug: string,
94		scope: MemoryScope,
95		currentSearch: Record<string, unknown> = {},
96		viewOverride?: MemoryView,
97	) {
98		const view =
99			viewOverride ??
100			(typeof currentSearch.view === "string"
101				? (currentSearch.view as string)
102				: undefined);
103		return {
104			to: "/$owner/memory" as const,
105			params: { owner: ownerSlug },
106			search: pruneSearch({
107				view: view && view !== "entities" ? view : undefined,
108				type: scope.kind === "type" ? scope.slug : undefined,
109				connection_ids: scope.kind === "connection" ? scope.ids : undefined,
110				agent: scope.kind === "agent" ? scope.id : undefined,
111				entity: scope.kind === "entity" ? scope.path : undefined,
112				// Drill-down keys never survive a scope change.
113				behavior: undefined,
114				schedule: undefined,
115				platforms: undefined,
116				feed_ids: undefined,
117				run_ids: undefined,
118				at: undefined,
119			}) as Record<string, string | undefined>,
120		};
121	}
122	
123	/**
124	 * Additive scope for the Events view: apply a filter patch while preserving
125	 * sibling event filters already in the URL. This is what makes the Events
126	 * toolbar dropdowns COMBINABLE (type + connection_ids + feed_ids + agent AND
127	 * together) rather than mutually exclusive like `memoryScopeSearch`. A patch
128	 * value of `undefined` clears that key. Events-only — Feeds/Entities
129	 * stay single-scope via `memoryScopeSearch`/`memoryBrowseTypeSearch`.
130	 */
131	export function memoryEventsFilterSearch(
132		ownerSlug: string,
133		currentSearch: Record<string, unknown>,
134		patch: Record<string, string | undefined>,
135	) {
136		return {
137			to: "/$owner/memory" as const,
138			params: { owner: ownerSlug },
139			search: pruneSearch({
140				...currentSearch,
141				view: "events",
142				...patch,
143			}) as Record<string, string | undefined>,
144		};
145	}
146	
147	/** Scope to an entity type (`?type=`), preserving the current view. */
148	export function memoryBrowseTypeSearch(
149		ownerSlug: string,
150		entityTypeSlug: string,
151		currentSearch: Record<string, unknown> = {},
152	) {
153		return memoryScopeSearch(
154			ownerSlug,
155			{ kind: "type", slug: entityTypeSlug },
156			currentSearch,
157		);
158	}
159	
160	/** Scope to a single entity (`?entity=<type>/<slug>`), preserving the view. */
161	export function memoryBrowseEntitySearch(
162		ownerSlug: string,
163		segments: EntityPathSegment[],
164		currentSearch: Record<string, unknown> = {},
165	) {
166		return memoryScopeSearch(
167			ownerSlug,
168			{ kind: "entity", path: entityPathToBrowsePath(segments) },
169			currentSearch,
170		);
171	}
172	
173	/** The `?entity=<type>/<slug>` scope, if any (type segments decoded). */
174	export function parseEntityScope(
175		search: Record<string, unknown>,
176	): string | undefined {
177		const raw =
178			typeof search.entity === "string" && search.entity.trim()
179				? search.entity.trim()
180				: undefined;
181		return raw ? decodeEntityBrowsePath(raw) : undefined;
182	}
183	
184	function pickMemoryView(
185		search: Record<string, unknown>,
186	): string | undefined {
187		const view =
188			typeof search.view === "string" && search.view.trim()
189				? search.view.trim()
190				: undefined;
191		// Only Events is non-default in the URL; entities + removed feeds collapse.
192		if (view === "events" || view === "feeds") return "events";
193		return undefined;
194	}
195	
196	function pickMemoryCreate(
197		search: Record<string, unknown>,
198	): string | undefined {
199		return search.create === true || search.create === "true" ? "true" : undefined;
200	}
201	
202	/** The normalized `?connection_ids=` scope, accepting router-coerced numbers. */
203	export function parseConnectionScope(
204		search: Record<string, unknown>,
205	): string | undefined {
206		const raw = search.connection_ids;
207		if (typeof raw === "number") return String(raw);
208		return typeof raw === "string" && raw.trim() ? raw.trim() : undefined;
209	}
210	
211	function pickRunScope(search: Record<string, unknown>): string | undefined {
212		const raw = search.run_ids;
213		if (typeof raw === "number") return String(raw);
214		return typeof raw === "string" && raw.trim() ? raw.trim() : undefined;
215	}
216	
217	function pickAgentScope(search: Record<string, unknown>): string | undefined {
218		const raw = search.agent ?? search.agent_id;
219		return typeof raw === "string" && raw.trim() ? raw.trim() : undefined;
220	}
221	
222	/** The `?agent=<agentId>` scope, if any. */
223	export function parseAgentScope(
224		search: Record<string, unknown>,
225	): string | undefined {
226		return pickAgentScope(search);
227	}
228	
229	function pickWatcherScope(search: Record<string, unknown>): string | undefined {
230		const raw = search.behavior;
231		if (typeof raw === "number") return String(raw);
232		return typeof raw === "string" && raw.trim() ? raw.trim() : undefined;
233	}
234	
235	/** The `?behavior=<id>` drill-down under an agent scope, if any. */
236	export function parseWatcherScope(
237		search: Record<string, unknown>,
238	): string | undefined {
239		return pickWatcherScope(search);
240	}
241	
242	function pickScheduleScope(search: Record<string, unknown>): string | undefined {
243		const raw = search.schedule;
244		return typeof raw === "string" && raw.trim() ? raw.trim() : undefined;
245	}
246	
247	/** The `?schedule=<id>` drill-down under an agent scope, if any. */
248	export function parseScheduleScope(
249		search: Record<string, unknown>,
250	): string | undefined {
251		return pickScheduleScope(search);
252	}
253	
254	/** Drill from an agent Behavior into its Events activity log. */
255	export function memoryWatcherDrillSearch(
256		ownerSlug: string,
257		agentId: string,
258		watcherId: string,
259	) {
260		const search: Record<string, string | undefined> = {
261			agent: agentId,
262			view: "events",
263			behavior: watcherId,
264			schedule: undefined,
265			platforms: undefined,
266			connection_ids: undefined,
267			run_ids: undefined,
268			feed_ids: undefined,
269			at: undefined,
270		};
271	
272		return {
273			to: "/$owner/memory" as const,
274			params: { owner: ownerSlug },
275			search: pruneSearch(search) as Record<string, string | undefined>,
276		};
277	}
278	
279	/** Drill from a connector or entity feed row into its Events activity log. */
280	export function memoryFeedDrillSearch(
281		ownerSlug: string,
282		feedId: number,
283		options?: { entityScope?: string; connectionScope?: string },
284	) {
285		return {
286			to: "/$owner/memory" as const,
287			params: { owner: ownerSlug },
288			search: pruneSearch({
289				view: "events",
290				feed_ids: String(feedId),
291				entity: options?.entityScope,
292				connection_ids: options?.connectionScope,
293				agent: undefined,
294				behavior: undefined,
295				schedule: undefined,
296				platforms: undefined,
297				run_ids: undefined,
298				at: undefined,
299			}) as Record<string, string | undefined>,
300		};
301	}
302	
303	/** Drill from a connection scope into Events for that connector's ingestion. */
304	export function memoryConnectionDrillSearch(
305		ownerSlug: string,
306		connectionId: number | string,
307	) {
308		return {
309			to: "/$owner/memory" as const,
310			params: { owner: ownerSlug },
311			search: pruneSearch({
312				view: "events",
313				connection_ids: String(connectionId),
314				feed_ids: undefined,
315				agent: undefined,
316				behavior: undefined,
317				at: undefined,
318			}) as Record<string, string | undefined>,
319		};
320	}
321	
322	/**
323	 * Canonical single-scope search used for legacy URLs and encoded entity/type
324	 * normalization. Additive Events filters are left intact by the redirect guard.
325	 */
326	export function canonicalMemorySearch(
327		search: Record<string, unknown>,
328	): Record<string, string | undefined> {
329		const entity = parseEntityScope(search);
330	
331		const type =
332			typeof search.type === "string" && search.type.trim()
