import { pickPeekSearch } from "@/lib/peek-search";
import { pruneSearch } from "@/lib/router-search";
import {
	decodeEntityBrowsePath,
	decodeEntityTypeParam,
	type EntityPathSegment,
} from "@/lib/url";

/**
 * Selected vs. idle row treatment for the nested memory entity-type rail.
 * Selected uses a quiet fill and bottom accent rather than a full primary ring.
 * The transparent idle border keeps row height stable.
 */
export const MEMORY_RAIL_ROW_ACTIVE =
	"bg-muted/50 text-foreground border-b-2 border-primary rounded-b-none";
export const MEMORY_RAIL_ROW_IDLE =
	"border-b-2 border-transparent text-muted-foreground hover:bg-accent/50 hover:text-foreground";

/**
 * The Memory view selected by `?view=`. Events (data stream + scope filters)
 * and Entities (types → records). Feed management lives on Connect; legacy
 * `?view=feeds` is treated as Events.
 */
export type MemoryView = "entities" | "events";

/** Parse an explicit `?view=`, or null when unset (the caller picks a default). */
export function parseMemoryView(value: unknown): MemoryView | null {
	if (value === "events") return "events";
	// Removed Memory Feeds tab — old deep links land on Events.
	if (value === "feeds") return "events";
	if (value === "entities") return "entities";
	return null;
}

/**
 * The active view given the URL `?view=` and whether a type/entity is scoped.
 * Default: a type or entity scope lands on Entities (its list / its record); the
 * unscoped home lands on Events.
 */
export function resolveMemoryView(
	value: unknown,
	hasEntityShapedScope: boolean,
): MemoryView {
	return parseMemoryView(value) ?? (hasEntityShapedScope ? "entities" : "events");
}

/** Format entity path segments as `type/slug/…` for the `?entity=` scope. */
export function entityPathToBrowsePath(segments: EntityPathSegment[]): string {
	return segments
		.map((segment) => `${segment.entity_type}/${segment.slug}`)
		.join("/");
}

/**
 * The parsed shape of a `/memory/$` splat: the entity type slug (first segment)
 * and, for entity detail, the full path. A bare `/memory` (no splat) parses to
 * `{ typeSlug: undefined }` — the events home.
 */
export type MemorySplat = {
	/** Raw (still URL-encoded) first path segment — the entity type. */
	typeSegment?: string;
	/** Full path after `/memory/` — `type` or `type/slug/...`. */
	path?: string;
	/** True when the splat addresses a single entity (has a slug after the type). */
	isEntityDetail: boolean;
};

export function parseMemorySplat(splat: string | undefined): MemorySplat {
	const trimmed = (splat ?? "").replace(/^\/+|\/+$/g, "");
	if (!trimmed) return { isEntityDetail: false };
	const segments = trimmed.split("/");
	return {
		typeSegment: segments[0],
		path: trimmed,
		isEntityDetail: segments.length > 1,
	};
}

/**
 * A single-scope Memory selection. These variants are mutually exclusive.
 */
export type MemoryScope =
	| { kind: "type"; slug: string }
	| { kind: "connection"; ids: string }
	| { kind: "agent"; id: string }
	| { kind: "entity"; path: string };

/**
 * Set one in-place scope on `/memory`, clear the other scopes, and preserve the
 * current view. `viewOverride` handles scopes that the current view cannot show.
 */
export function memoryScopeSearch(
	ownerSlug: string,
	scope: MemoryScope,
	currentSearch: Record<string, unknown> = {},
	viewOverride?: MemoryView,
) {
	const view =
		viewOverride ??
		(typeof currentSearch.view === "string"
			? (currentSearch.view as string)
			: undefined);
	return {
		to: "/$owner/memory" as const,
		params: { owner: ownerSlug },
		search: pruneSearch({
			view: view && view !== "entities" ? view : undefined,
			type: scope.kind === "type" ? scope.slug : undefined,
			connection_ids: scope.kind === "connection" ? scope.ids : undefined,
			agent: scope.kind === "agent" ? scope.id : undefined,
			entity: scope.kind === "entity" ? scope.path : undefined,
			// Drill-down keys never survive a scope change.
			behavior: undefined,
			schedule: undefined,
			platforms: undefined,
			feed_ids: undefined,
			run_ids: undefined,
			at: undefined,
		}) as Record<string, string | undefined>,
	};
}

/**
 * Additive scope for the Events view: apply a filter patch while preserving
 * sibling event filters already in the URL. This is what makes the Events
 * toolbar dropdowns COMBINABLE (type + connection_ids + feed_ids + agent AND
 * together) rather than mutually exclusive like `memoryScopeSearch`. A patch
 * value of `undefined` clears that key. Events-only — Feeds/Entities
 * stay single-scope via `memoryScopeSearch`/`memoryBrowseTypeSearch`.
 */
export function memoryEventsFilterSearch(
	ownerSlug: string,
	currentSearch: Record<string, unknown>,
	patch: Record<string, string | undefined>,
) {
	return {
		to: "/$owner/memory" as const,
		params: { owner: ownerSlug },
		search: pruneSearch({
			...currentSearch,
			view: "events",
			...patch,
		}) as Record<string, string | undefined>,
	};
}

/** Scope to an entity type (`?type=`), preserving the current view. */
export function memoryBrowseTypeSearch(
	ownerSlug: string,
	entityTypeSlug: string,
	currentSearch: Record<string, unknown> = {},
) {
	return memoryScopeSearch(
		ownerSlug,
		{ kind: "type", slug: entityTypeSlug },
		currentSearch,
	);
}

/** Scope to a single entity (`?entity=<type>/<slug>`), preserving the view. */
export function memoryBrowseEntitySearch(
	ownerSlug: string,
	segments: EntityPathSegment[],
	currentSearch: Record<string, unknown> = {},
) {
	return memoryScopeSearch(
		ownerSlug,
		{ kind: "entity", path: entityPathToBrowsePath(segments) },
		currentSearch,
	);
}

/** The `?entity=<type>/<slug>` scope, if any (type segments decoded). */
export function parseEntityScope(
	search: Record<string, unknown>,
): string | undefined {
	const raw =
		typeof search.entity === "string" && search.entity.trim()
			? search.entity.trim()
			: undefined;
	return raw ? decodeEntityBrowsePath(raw) : undefined;
}

function pickMemoryView(
	search: Record<string, unknown>,
): string | undefined {
	const view =
		typeof search.view === "string" && search.view.trim()
			? search.view.trim()
			: undefined;
	// Only Events is non-default in the URL; entities + removed feeds collapse.
	if (view === "events" || view === "feeds") return "events";
	return undefined;
}

function pickMemoryCreate(
	search: Record<string, unknown>,
): string | undefined {
	return search.create === true || search.create === "true" ? "true" : undefined;
}

/** The normalized `?connection_ids=` scope, accepting router-coerced numbers. */
export function parseConnectionScope(
	search: Record<string, unknown>,
): string | undefined {
	const raw = search.connection_ids;
	if (typeof raw === "number") return String(raw);
	return typeof raw === "string" && raw.trim() ? raw.trim() : undefined;
}

function pickRunScope(search: Record<string, unknown>): string | undefined {
	const raw = search.run_ids;
	if (typeof raw === "number") return String(raw);
	return typeof raw === "string" && raw.trim() ? raw.trim() : undefined;
}

function pickAgentScope(search: Record<string, unknown>): string | undefined {
	const raw = search.agent ?? search.agent_id;
	return typeof raw === "string" && raw.trim() ? raw.trim() : undefined;
}

/** The `?agent=<agentId>` scope, if any. */
export function parseAgentScope(
	search: Record<string, unknown>,
): string | undefined {
	return pickAgentScope(search);
}

function pickWatcherScope(search: Record<string, unknown>): string | undefined {
	const raw = search.behavior;
	if (typeof raw === "number") return String(raw);
	return typeof raw === "string" && raw.trim() ? raw.trim() : undefined;
}

/** The `?behavior=<id>` drill-down under an agent scope, if any. */
export function parseWatcherScope(
	search: Record<string, unknown>,
): string | undefined {
	return pickWatcherScope(search);
}

function pickScheduleScope(search: Record<string, unknown>): string | undefined {
	const raw = search.schedule;
	return typeof raw === "string" && raw.trim() ? raw.trim() : undefined;
}

/** The `?schedule=<id>` drill-down under an agent scope, if any. */
export function parseScheduleScope(
	search: Record<string, unknown>,
): string | undefined {
	return pickScheduleScope(search);
}

/** Drill from an agent Behavior into its Events activity log. */
export function memoryWatcherDrillSearch(
	ownerSlug: string,
	agentId: string,
	watcherId: string,
) {
	const search: Record<string, string | undefined> = {
		agent: agentId,
		view: "events",
		behavior: watcherId,
		schedule: undefined,
		platforms: undefined,
		connection_ids: undefined,
		run_ids: undefined,
		feed_ids: undefined,
		at: undefined,
	};

	return {
		to: "/$owner/memory" as const,
		params: { owner: ownerSlug },
		search: pruneSearch(search) as Record<string, string | undefined>,
	};
}

/** Drill from a connector or entity feed row into its Events activity log. */
export function memoryFeedDrillSearch(
	ownerSlug: string,
	feedId: number,
	options?: { entityScope?: string; connectionScope?: string },
) {
	return {
		to: "/$owner/memory" as const,
		params: { owner: ownerSlug },
		search: pruneSearch({
			view: "events",
			feed_ids: String(feedId),
			entity: options?.entityScope,
			connection_ids: options?.connectionScope,
			agent: undefined,
			behavior: undefined,
			schedule: undefined,
			platforms: undefined,
			run_ids: undefined,
			at: undefined,
		}) as Record<string, string | undefined>,
	};
}

/** Drill from a connection scope into Events for that connector's ingestion. */
export function memoryConnectionDrillSearch(
	ownerSlug: string,
	connectionId: number | string,
) {
	return {
		to: "/$owner/memory" as const,
		params: { owner: ownerSlug },
		search: pruneSearch({
			view: "events",
			connection_ids: String(connectionId),
			feed_ids: undefined,
			agent: undefined,
			behavior: undefined,
			at: undefined,
		}) as Record<string, string | undefined>,
	};
}

/**
 * Canonical single-scope search used for legacy URLs and encoded entity/type
 * normalization. Additive Events filters are left intact by the redirect guard.
 */
export function canonicalMemorySearch(
	search: Record<string, unknown>,
): Record<string, string | undefined> {
	const entity = parseEntityScope(search);

	const type =
		typeof search.type === "string" && search.type.trim()
			? decodeEntityTypeParam(search.type.trim())
			: undefined;
	const view = pickMemoryView(search);
	const create = pickMemoryCreate(search);
	const connectionIds = parseConnectionScope(search);
	const agentId = pickAgentScope(search);
	const runIds = pickRunScope(search);
	const peekSearch = pickPeekSearch(search);

	if (entity) {
		return { ...pruneSearch({ view, entity, create }), ...peekSearch };
	}
	if (type) {
		return { ...pruneSearch({ view, type, create }), ...peekSearch };
	}
	if (connectionIds) {
		return {
			...pruneSearch({ view, connection_ids: connectionIds }),
			...peekSearch,
		};
	}
	if (agentId) {
		const watcher = pickWatcherScope(search);
		const schedule = pickScheduleScope(search);
		const platforms =
			typeof search.platforms === "string" && search.platforms.trim()
				? search.platforms.trim()
				: undefined;
		return {
			...pruneSearch({
				view,
				agent: agentId,
				behavior: watcher,
				schedule,
				platforms,
				run_ids: runIds,
			}),
			...peekSearch,
		};
	}
	return {
		...pruneSearch({ view, create, run_ids: runIds }),
		...peekSearch,
	};
}

/**
 * Normalize double-encoded entity/type values and stale `entity` + `type`
 * pairs without rewriting additive Events filters.
 */
export function memorySearchNeedsCanonicalRedirect(
	search: Record<string, unknown>,
): Record<string, string | undefined> | null {
	const canonical = canonicalMemorySearch(search);
	const rawType =
		typeof search.type === "string" && search.type.trim()
			? search.type.trim()
			: undefined;
	const rawEntity =
		typeof search.entity === "string" && search.entity.trim()
			? search.entity.trim()
			: undefined;

	if (rawEntity && canonical.entity && rawEntity !== canonical.entity) {
		return canonical;
	}
	if (rawType && canonical.type && rawType !== canonical.type) {
		return canonical;
	}
	if (rawEntity && rawType) {
		return canonical;
	}
	return null;
}

/**
 * Reverse-lookup: given the connector groups and a set of selected connection
 * ids, return the `connector_key` that owns all of them (the connector to expand
 * in the cascade dropdown / to build a "Manage" link for). Returns undefined
 * when any id is unmatched or belongs to another connector. Structurally typed
 * so this lib stays free of the connections-API import.
 */
export function connectorForConnectionIds(
	groups: ReadonlyArray<{
		connector_key: string;
		connections: ReadonlyArray<{ id: number }>;
	}>,
	connectionIds: ReadonlySet<string>,
): string | undefined {
	if (connectionIds.size === 0) return undefined;
	let match: string | undefined;
	const matchedIds = new Set<string>();
	for (const group of groups) {
		for (const connection of group.connections) {
			const id = String(connection.id);
			if (connectionIds.has(id)) {
				if (match && match !== group.connector_key) return undefined;
				match = group.connector_key;
				matchedIds.add(id);
			}
		}
	}
	return matchedIds.size === connectionIds.size ? match : undefined;
}

/** In-place scope for the built-in Members list (`?type=$member&view=entities`). */
export function memoryMemberListSearch(ownerSlug: string) {
	return {
		to: "/$owner/memory" as const,
		params: { owner: ownerSlug },
		search: pruneSearch({
			type: "$member",
			view: "entities",
		}) as Record<string, string | undefined>,
	};
}

/** Frontend route for a memory-scoped entity detail (refs, login callbacks). */
export function buildMemoryEntityScopePath(
	owner: string,
	segments: EntityPathSegment[],
): string {
	const entity = entityPathToBrowsePath(segments);
	const params = new URLSearchParams({ entity, view: "entities" });
	return `/${owner}/memory?${params.toString()}`;
}

/** Link back to the memory home, clearing every scope + drill-down (keeps view). */
export function memoryBrowseHomeSearch(
	currentSearch: Record<string, unknown> = {},
) {
	return {
		to: "/$owner/memory" as const,
		search: pruneSearch({
			view: typeof currentSearch.view === "string" ? currentSearch.view : undefined,
			type: undefined,
			entity: undefined,
			connection_ids: undefined,
			agent: undefined,
			behavior: undefined,
			schedule: undefined,
			platforms: undefined,
			feed_ids: undefined,
			run_ids: undefined,
			at: undefined,
			create_type: undefined,
			create: undefined,
		}),
	};
}

/** Open entity-type creation under the Context destination. */
export function memoryCreateEntityTypeSearch(ownerSlug: string) {
	return {
		to: "/$owner/memory" as const,
		params: { owner: ownerSlug },
		search: pruneSearch({
			view: "entities",
			create_type: "true",
		}) as Record<string, string | undefined>,
	};
}

