30	function useMemorySearch(): Record<string, unknown> {
31		const location = useLocation();
32		return (location.search ?? {}) as Record<string, unknown>;
33	}
34	
35	/**
36	 * Events scope toolbar: Type / Agent / Connector→Connection→Feed.
37	 * AND-composes via `memoryEventsFilterSearch`. Scopes default from the URL
38	 * when props are omitted (so EventsFilterBar can mount this without wiring).
39	 */
40	export function MemoryScopeBar({
41		ownerSlug,
42		typeScope: typeScopeProp,
43		agentScope: agentScopeProp,
44		connectionScope: connectionScopeProp,
45		feedScope: feedScopeProp,
46	}: {
47		ownerSlug: string;
48		typeScope?: string;
49		agentScope?: string;
50		connectionScope?: string;
51		feedScope?: string;
52	}) {
53		const search = useMemorySearch();
54		const typeRaw =
55			typeof search.type === "string" && search.type.trim()
56				? search.type.trim()
57				: undefined;
58		const typeScope =
59			typeScopeProp ?? (typeRaw ? decodeEntityTypeParam(typeRaw) : undefined);
60		const agentScope = agentScopeProp ?? parseAgentScope(search);
61		const connectionScope =
62			connectionScopeProp ?? parseConnectionScope(search);
63		const feedScope =
64			feedScopeProp ??
65			(typeof search.feed_ids === "string"
66				? search.feed_ids
67				: typeof search.feed_ids === "number"
68					? String(search.feed_ids)
69					: undefined);
70	
71		return (
72			<div className="flex min-w-0 flex-wrap items-center gap-2">
73				<TypeDropdown ownerSlug={ownerSlug} typeScope={typeScope} />
74				<AgentDropdown ownerSlug={ownerSlug} agentScope={agentScope} />
75				<ConnectorCascade
76					ownerSlug={ownerSlug}
77					connectionScope={connectionScope}
78					feedScope={feedScope}
79				/>
80			</div>
81		);
82	}
83	
84	/**
85	 * A trigger button that reads as a labelled dropdown ("Label: value ▾").
86	 * `forwardRef` + `{...rest}` are essential: the enabled trigger is passed to
87	 * `<PopoverTrigger asChild>`, whose Slot injects onClick/data-state/ref onto its
88	 * child — those must reach the real `<button>`, or the popover never opens.
89	 */
90	const ScopeTrigger = React.forwardRef<
91		HTMLButtonElement,
92		{
93			open?: boolean;
94			label: string;
95			value?: string;
96			disabled?: boolean;
97			disabledReason?: string;
98		} & React.ComponentPropsWithoutRef<typeof Button>
99	>(function ScopeTrigger(
100		{ open, label, value, disabled, disabledReason, ...rest },
101		ref,
102	) {
103		const button = (
104			<Button
105				ref={ref}
106				variant="outline"
107				size="sm"
108				disabled={disabled}
109				aria-expanded={open}
110				className="h-8 gap-1.5 text-xs"
111				{...rest}
112			>
113				<span className="text-muted-foreground">{label}</span>
114				{value ? (
115					<span className="max-w-[10rem] truncate font-medium">{value}</span>
116				) : (
117					<span className="text-muted-foreground">Any</span>
118				)}
119				<ChevronDown className="h-3.5 w-3.5 shrink-0 opacity-60" />
120			</Button>
121		);
122		if (disabled && disabledReason) {
123			return (
124				<Tooltip>
125					<TooltipTrigger asChild>
126						{/* A disabled button swallows pointer events, so wrap it to keep the
127						    tooltip reachable. */}
128						<span className="inline-flex">{button}</span>
129					</TooltipTrigger>
130					<TooltipContent>{disabledReason}</TooltipContent>
131				</Tooltip>
132			);
133		}
134		return button;
135	});
136	
137	function TypeDropdown({
138		ownerSlug,
139		typeScope,
140	}: {
141		ownerSlug: string;
142		typeScope?: string;
143	}) {
144		const navigate = useNavigate();
145		const currentSearch = useMemorySearch();
146		const { visible } = useVisibleEntityTypes(ownerSlug);
147		const active = visible.find((et) => et.slug === typeScope);
148	
149		const selectType = (slug: string) => {
150			void navigate(
151				memoryEventsFilterSearch(ownerSlug, currentSearch, {
152					entity: undefined,
153					create: undefined,
154					type: slug,
155				}),
156			);
157		};
158	
159		const clearType = () => {
160			void navigate(
161				memoryEventsFilterSearch(ownerSlug, currentSearch, {
162					type: undefined,
163				}),
164			);
165		};
166	
167		return (
168			<Combobox
169				contentClassName="w-72"
170				searchPlaceholder="Search types..."
171				emptyText="No entity types"
172				trigger={(open) => (
173					<ScopeTrigger open={open} label="Type" value={active?.name} />
174				)}
175			>
176				{(close) => (
177					<>
178						{typeScope ? (
179							<CommandItem
180								onSelect={() => {
181									clearType();
182									close();
183								}}
184								className="text-muted-foreground"
185							>
186								Clear type
187							</CommandItem>
188						) : null}
189						{visible.map((et) => (
190							<CommandItem
191								key={et.id}
192								onSelect={() => {
193									selectType(et.slug);
194									close();
195								}}
196								className="group gap-2"
197							>
198								<Check className={cnCheck(et.slug === typeScope)} />
199								<EntityIcon icon={et.icon} className="h-4 w-4 shrink-0" />
200								<span className="min-w-0 flex-1 truncate">{et.name}</span>
201								{typeof et.entity_count === "number" ? (
202									<span className="shrink-0 text-xs tabular-nums text-muted-foreground">
203										{et.entity_count}
204									</span>
205								) : null}
206								<ManageGear
207									to="/$owner/entity-types/$slug"
208									params={{ owner: ownerSlug, slug: et.slug }}
209									label={et.name}
210								/>
211							</CommandItem>
212						))}
213						<CommandItem
214							onSelect={() => {
215								void navigate(memoryCreateEntityTypeSearch(ownerSlug));
216								close();
217							}}
218							className="text-muted-foreground"
219						>
220							<Plus className="h-4 w-4 shrink-0" />
221							Add entity type
222						</CommandItem>
223					</>
224				)}
225			</Combobox>
226		);
227	}
228	
229	function AgentDropdown({
230		ownerSlug,
231		agentScope,
232	}: {
233		ownerSlug: string;
234		agentScope?: string;
235	}) {
236		const navigate = useNavigate();
237		const currentSearch = useMemorySearch();
238		const { data: agents = [] } = useAgents();
239		const sorted = useMemo(
240			() => [...agents].sort((a, b) => a.name.localeCompare(b.name)),
241			[agents],
242		);
243		const active = sorted.find((a) => a.agentId === agentScope);
244	
245		const selectAgent = (agentId: string) => {
246			void navigate(
247				memoryEventsFilterSearch(
248					ownerSlug,
249					currentSearch,
250					agentEventFilterPatch(currentSearch, agentId),
251				),
252			);
253		};
254	
255		const clearAgent = () => {
256			void navigate(
257				memoryEventsFilterSearch(
258					ownerSlug,
259					currentSearch,
260					agentEventFilterPatch(currentSearch, undefined),
261				),
262			);
263		};
264	
265		return (
266			<Combobox
267				contentClassName="w-72"
268				searchPlaceholder="Search agents..."
269				emptyText="No agents"
270				trigger={(open) => (
271					<ScopeTrigger open={open} label="Agent" value={active?.name} />
272				)}
273			>
274				{(close) => (
275					<>
276						{agentScope ? (
277							<CommandItem
278								onSelect={() => {
279									clearAgent();
280									close();
281								}}
282								className="text-muted-foreground"
283							>
284								Clear agent
285							</CommandItem>
286						) : null}
287						{sorted.map((agent) => (
288							<CommandItem
289								key={agent.agentId}
290								onSelect={() => {
291									selectAgent(agent.agentId);
292									close();
293								}}
294								className="gap-2"
295							>
296								<Check className={cnCheck(agent.agentId === agentScope)} />
297								<span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-md bg-muted text-[10px] font-medium">
298									{agent.name.trim().charAt(0).toUpperCase() || "?"}
299								</span>
300								<span className="min-w-0 flex-1 truncate">{agent.name}</span>
301							</CommandItem>
302						))}
303					</>
304				)}
305			</Combobox>
306		);
307	}
308	
309	function agentEventFilterPatch(
310		currentSearch: Record<string, unknown>,
311		agent: string | undefined,
312	): Record<string, string | undefined> {
313		const patch: Record<string, string | undefined> = {
314			agent,
315			behavior: undefined,
316			schedule: undefined,
317			platforms: undefined,
318		};
319		if (currentSearch.schedule != null) {
320			patch.run_ids = undefined;
321		}
322		if (
323			typeof currentSearch.platforms === "string" &&
324			currentSearch.platforms.trim().length > 0
325		) {
326			patch.connection_ids = undefined;
327			patch.feed_ids = undefined;
328		}
329		return patch;
330	}
331	
332	function ConnectorCascade({
333		ownerSlug,
334		connectionScope,
335		feedScope,
336	}: {
337		ownerSlug: string;
338		connectionScope?: string;
339		feedScope?: string;
340	}) {
341		const { groups } = useMemoryConnectorGroups();
342	
343		const selectedIds = useMemo(
344			() =>
345				new Set(
346					(connectionScope ?? "")
347						.split(",")
348						.map((s) => s.trim())
349						.filter(Boolean),
350				),
351			[connectionScope],
352		);
353	
354		// The connector that owns the current connection scope, if the scope is a
355		// single connector's connection(s) — drives the Connector trigger label and
356		// which connector's connections/feeds the later dropdowns show.
357		const scopedConnectorKey = connectorForConnectionIds(groups, selectedIds);
358		const scopedGroup = groups.find((g) => g.connector_key === scopedConnectorKey);
359		const singleConnectionId =
360			selectedIds.size === 1
361				? Number([...selectedIds][0])
362				: undefined;
363	
364		return (
365			<>
366				<ConnectorDropdown
367					ownerSlug={ownerSlug}
368					groups={groups}
369					scopedGroup={scopedGroup}
370				/>
371				{scopedGroup ? (
372					<ConnectionDropdown
373						ownerSlug={ownerSlug}
374						group={scopedGroup}
375						selectedIds={selectedIds}
376					/>
377				) : null}
378				{singleConnectionId ? (
379					<FeedDropdown
380						ownerSlug={ownerSlug}
381						connectionId={singleConnectionId}
382						feedScope={feedScope}
383					/>
384				) : null}
385			</>
386		);
387	}
388	
389	function ConnectorDropdown({
390		ownerSlug,
391		groups,
392		scopedGroup,
393	}: {
394		ownerSlug: string;
395		groups: ReturnType<typeof useMemoryConnectorGroups>["groups"];
396		scopedGroup?: ReturnType<
397			typeof useMemoryConnectorGroups
398		>["groups"][number];
399	}) {
400		const navigate = useNavigate();
401		const currentSearch = useMemorySearch();
402	
403		const scopeToConnector = (
404			group: ReturnType<typeof useMemoryConnectorGroups>["groups"][number],
405		) => {
406			const ids = group.connections.map((c) => String(c.id)).join(",");
407			if (!ids) return;
408			void navigate(
409				memoryEventsFilterSearch(ownerSlug, currentSearch, {
410					connection_ids: ids,
411					// Switching connector invalidates any prior feed filter.
412					feed_ids: undefined,
413				}),
414			);
415		};
416	
417		const clearConnector = () => {
418			void navigate(
419				memoryEventsFilterSearch(ownerSlug, currentSearch, {
420					connection_ids: undefined,
421					feed_ids: undefined,
422				}),
423			);
424		};
425	
426		const label = scopedGroup?.connector_name ?? scopedGroup?.connector_key;
427	
428		return (
429			<Combobox
430				contentClassName="w-72"
431				searchPlaceholder="Search connectors..."
432				emptyText="No connectors"
433				trigger={(open) => (
434					<ScopeTrigger open={open} label="Connector" value={label} />
435				)}
436			>
437				{(close) => (
438					<>
439						{scopedGroup ? (
440							<CommandItem
441								onSelect={() => {
442									clearConnector();
443									close();
444								}}
445								className="text-muted-foreground"
446							>
447								Clear connector
448							</CommandItem>
449						) : null}
450						{groups.map((group) => {
451							const name = group.connector_name ?? group.connector_key;
452							return (
453								<CommandItem
454									key={group.connector_key}
455									disabled={group.connections.length === 0}
456									onSelect={() => {
457										scopeToConnector(group);
458										close();
459									}}
460									className="group gap-2"
461								>
462									<Check
463										className={cnCheck(
464											group.connector_key === scopedGroup?.connector_key,
465										)}
466									/>
467									<ConnectorMark
468										plain
469										name={name}
470										faviconDomain={group.favicon_domain}
471										className="h-5 w-5 shrink-0 rounded-md text-[10px]"
472									/>
473									<span className="min-w-0 flex-1 truncate">{name}</span>
474									{group.connection_count > 0 ? (
475										<span className="shrink-0 text-xs tabular-nums text-muted-foreground">
476											{group.connection_count}
477										</span>
478									) : null}
479									<ManageGear
480										to="/$owner/connectors/$connectorKey"
481										params={{ owner: ownerSlug, connectorKey: group.connector_key }}
482										label={name}
483									/>
484								</CommandItem>
485							);
486						})}
487						<AddRow
488							to="/$owner/connectors/create"
489							params={{ owner: ownerSlug }}
490							label="Add connector"
491							onSelect={close}
492						/>
493					</>
494				)}
495			</Combobox>
496		);
497	}
498	
499	function ConnectionDropdown({
500		ownerSlug,
501		group,
502		selectedIds,
503	}: {
504		ownerSlug: string;
505		group: ReturnType<typeof useMemoryConnectorGroups>["groups"][number];
506		selectedIds: ReadonlySet<string>;
507	}) {
508		const navigate = useNavigate();
509		const currentSearch = useMemorySearch();
510		// The label reads the selected connection only when exactly one is scoped;
511		// scoping the whole connector selects them all, which the Connector trigger
512		// already conveys.
513		const single =
514			selectedIds.size === 1
515				? group.connections.find((c) => selectedIds.has(String(c.id)))
516				: undefined;
517	
518		const selectConnection = (id: number) => {
519			void navigate(
520				memoryEventsFilterSearch(ownerSlug, currentSearch, {
521					connection_ids: String(id),
522					// Narrowing connection drops a feed scoped to a sibling.
523					feed_ids: undefined,
524				}),
525			);
526		};
527	
528		const label = single
529			? connectionLabel({
530					display_name: single.display_name,
531					connector_name: group.connector_name,
532					connector_key: group.connector_key,
533				})
534			: "All connections";
535	
536		return (
537			<Combobox
538				contentClassName="w-72"
539				searchPlaceholder="Search connections..."
540				emptyText="No connections"
541				trigger={(open) => (
542					<ScopeTrigger open={open} label="Connection" value={label} />
543				)}
544			>
545				{(close) =>
546					group.connections.map((connection) => {
547						const name = connectionLabel({
548							display_name: connection.display_name,
549							connector_name: group.connector_name,
550							connector_key: group.connector_key,
551						});
552						return (
553							<CommandItem
554								key={connection.id}
555								onSelect={() => {
556									selectConnection(connection.id);
557									close();
558								}}
559								className="group gap-2"
560							>
561								<Check className={cnCheck(selectedIds.has(String(connection.id)))} />
562								<span className="min-w-0 flex-1 truncate">{name}</span>
563								{connection.feed_count > 0 ? (
564									<span className="shrink-0 text-xs tabular-nums text-muted-foreground">
565										{connection.feed_count}
566									</span>
567								) : null}
568								<ManageGear
569									to="/$owner/connectors/$connectorKey/$connectionId"
570									params={{
571										owner: ownerSlug,
572										connectorKey: group.connector_key,
573										connectionId: String(connection.id),
574									}}
575									label={name}
576								/>
577							</CommandItem>
578						);
579					})
580				}
581			</Combobox>
582		);
583	}
584	
585	/**
586	 * The Feed leaf of the cascade. Only rendered once a single connection is
587	 * scoped, so `useFeeds` fires exactly one query. Events-only: selecting a feed
588	 * adds a `feed_ids` filter (combining with the connection filter).
589	 */
590	function FeedDropdown({
591		ownerSlug,
592		connectionId,
593		feedScope,
594	}: {
595		ownerSlug: string;
596		connectionId: number;
597		feedScope?: string;
598	}) {
599		const navigate = useNavigate();
600		const currentSearch = useMemorySearch();
601		const { data: feeds = [], isLoading } = useFeeds(connectionId);
602		const selectedIds = useMemo(
603			() =>
604				new Set(
605					(feedScope ?? "")
606						.split(",")
607						.map((s) => s.trim())
608						.filter(Boolean),
609				),
610			[feedScope],
611		);
612		const single =
613			selectedIds.size === 1
614				? feeds.find((f) => selectedIds.has(String(f.id)))
615				: undefined;
616	
617		const selectFeed = (feed: FeedItem) => {
618			void navigate(
619				memoryEventsFilterSearch(ownerSlug, currentSearch, {
620					connection_ids: String(connectionId),
621					feed_ids: String(feed.id),
622				}),
623			);
624		};
625	
626		const clearFeed = () => {
627			void navigate(
628				memoryEventsFilterSearch(ownerSlug, currentSearch, {
629					connection_ids: String(connectionId),
630					feed_ids: undefined,
631				}),
632			);
633		};
634	
635		return (
636			<Combobox
637				contentClassName="w-72"
638				searchPlaceholder="Search feeds..."
639				emptyText={isLoading ? "Loading feeds..." : "No feeds"}
640				trigger={(open) => (
641					<ScopeTrigger
642						open={open}
643						label="Feed"
644						value={single ? feedLabel(single) : undefined}
645					/>
646				)}
647			>
648				{(close) => (
649					<>
650						{selectedIds.size > 0 ? (
651							<CommandItem
652								onSelect={() => {
653									clearFeed();
654									close();
655								}}
656								className="text-muted-foreground"
657							>
658								Clear feed
659							</CommandItem>
660						) : null}
661						{feeds.map((feed) => (
662							<CommandItem
663								key={feed.id}
664								onSelect={() => {
665									selectFeed(feed);
666									close();
667								}}
668								className="gap-2"
669							>
670								<Check className={cnCheck(selectedIds.has(String(feed.id)))} />
671								<span className="min-w-0 flex-1 truncate">{feedLabel(feed)}</span>
672							</CommandItem>
673						))}
674					</>
675				)}
676			</Combobox>
677		);
678	}
679	
680	function feedLabel(feed: FeedItem): string {
681		return feed.display_name?.trim() || feed.feed_key;
682	}
683	
684	/**
685	 * The hover-reveal "Manage <x>" gear inside a dropdown row. Unlike the rail's
686	 * `MemoryRailSettingsLink`, this lives inside a selectable `cmdk` item, so it
687	 * stops propagation: clicking the gear navigates to the settings route without
688	 * also firing the row's `onSelect` (which would scope + close the popover).
689	 */
690	function ManageGear({
691		to,
692		params,
693		label,
694	}: {
695		to: string;
696		params: Record<string, string>;
697		label: string;
698	}) {
699		return (
700			<Link
701				to={to}
702				params={params}
703				onClick={(e) => e.stopPropagation()}
704				onPointerDown={(e) => e.stopPropagation()}
705				className="shrink-0 rounded-md p-1 text-muted-foreground opacity-0 transition-opacity hover:text-foreground group-hover:opacity-100 focus-visible:opacity-100"
706				aria-label={`Manage ${label}`}
707			>
708				<Settings2 className="h-3.5 w-3.5" />
709			</Link>
710		);
711	}
712	
713	function AddRow({
714		to,
715		params,
716		label,
717		onSelect,
718	}: {
719		to: "/$owner/entity-types/new" | "/$owner/connectors/create";
720		params: { owner: string };
721		label: string;
722		onSelect: () => void;
723	}) {
724		return (
725			<CommandItem asChild onSelect={onSelect} className="text-muted-foreground">
726				<Link to={to} params={params} className="flex items-center gap-2">
727					<Plus className="h-4 w-4 shrink-0" />
728					{label}
729				</Link>
730			</CommandItem>
731		);
732	}
733	
734	function cnCheck(selected: boolean): string {
735		return selected
736			? "h-4 w-4 shrink-0 opacity-100"
737			: "h-4 w-4 shrink-0 opacity-0";
738	}
