import { Link, useLocation, useNavigate } from "@tanstack/react-router";
import { Check, ChevronDown, Plus, Settings2 } from "lucide-react";
import * as React from "react";
import { useMemo } from "react";
import { ConnectorMark } from "@/components/connectors/connector-display";
import { useVisibleEntityTypes } from "@/components/memory/use-visible-entity-types";
import { Button } from "@/components/ui/button";
import { Combobox } from "@/components/ui/combobox";
import { CommandItem } from "@/components/ui/command";
import { EntityIcon } from "@/components/ui/entity-icon";
import {
	Tooltip,
	TooltipContent,
	TooltipTrigger,
} from "@/components/ui/tooltip";
import { useAgents } from "@/lib/api/agents";
import { type FeedItem, useFeeds } from "@/lib/api/connections";
import { connectionLabel } from "@/lib/connection-label";
import {
	connectorForConnectionIds,
	memoryCreateEntityTypeSearch,
	memoryEventsFilterSearch,
	parseAgentScope,
	parseConnectionScope,
} from "@/lib/memory-browse";
import { decodeEntityTypeParam } from "@/lib/url";
import { useMemoryConnectorGroups } from "./memory-connector-groups";

/** Live URL search for additive Events filters — must preserve sibling keys. */
function useMemorySearch(): Record<string, unknown> {
	const location = useLocation();
	return (location.search ?? {}) as Record<string, unknown>;
}

/**
 * Events scope toolbar: Type / Agent / Connector→Connection→Feed.
 * AND-composes via `memoryEventsFilterSearch`. Scopes default from the URL
 * when props are omitted (so EventsFilterBar can mount this without wiring).
 */
export function MemoryScopeBar({
	ownerSlug,
	typeScope: typeScopeProp,
	agentScope: agentScopeProp,
	connectionScope: connectionScopeProp,
	feedScope: feedScopeProp,
}: {
	ownerSlug: string;
	typeScope?: string;
	agentScope?: string;
	connectionScope?: string;
	feedScope?: string;
}) {
	const search = useMemorySearch();
	const typeRaw =
		typeof search.type === "string" && search.type.trim()
			? search.type.trim()
			: undefined;
	const typeScope =
		typeScopeProp ?? (typeRaw ? decodeEntityTypeParam(typeRaw) : undefined);
	const agentScope = agentScopeProp ?? parseAgentScope(search);
	const connectionScope =
		connectionScopeProp ?? parseConnectionScope(search);
	const feedScope =
		feedScopeProp ??
		(typeof search.feed_ids === "string"
			? search.feed_ids
			: typeof search.feed_ids === "number"
				? String(search.feed_ids)
				: undefined);

	return (
		<div className="flex min-w-0 flex-wrap items-center gap-2">
			<TypeDropdown ownerSlug={ownerSlug} typeScope={typeScope} />
			<AgentDropdown ownerSlug={ownerSlug} agentScope={agentScope} />
			<ConnectorCascade
				ownerSlug={ownerSlug}
				connectionScope={connectionScope}
				feedScope={feedScope}
			/>
		</div>
	);
}

/**
 * A trigger button that reads as a labelled dropdown ("Label: value ▾").
 * `forwardRef` + `{...rest}` are essential: the enabled trigger is passed to
 * `<PopoverTrigger asChild>`, whose Slot injects onClick/data-state/ref onto its
 * child — those must reach the real `<button>`, or the popover never opens.
 */
const ScopeTrigger = React.forwardRef<
	HTMLButtonElement,
	{
		open?: boolean;
		label: string;
		value?: string;
		disabled?: boolean;
		disabledReason?: string;
	} & React.ComponentPropsWithoutRef<typeof Button>
>(function ScopeTrigger(
	{ open, label, value, disabled, disabledReason, ...rest },
	ref,
) {
	const button = (
		<Button
			ref={ref}
			variant="outline"
			size="sm"
			disabled={disabled}
			aria-expanded={open}
			className="h-8 gap-1.5 text-xs"
			{...rest}
		>
			<span className="text-muted-foreground">{label}</span>
			{value ? (
				<span className="max-w-[10rem] truncate font-medium">{value}</span>
			) : (
				<span className="text-muted-foreground">Any</span>
			)}
			<ChevronDown className="h-3.5 w-3.5 shrink-0 opacity-60" />
		</Button>
	);
	if (disabled && disabledReason) {
		return (
			<Tooltip>
				<TooltipTrigger asChild>
					{/* A disabled button swallows pointer events, so wrap it to keep the
					    tooltip reachable. */}
					<span className="inline-flex">{button}</span>
				</TooltipTrigger>
				<TooltipContent>{disabledReason}</TooltipContent>
			</Tooltip>
		);
	}
	return button;
});

function TypeDropdown({
	ownerSlug,
	typeScope,
}: {
	ownerSlug: string;
	typeScope?: string;
}) {
	const navigate = useNavigate();
	const currentSearch = useMemorySearch();
	const { visible } = useVisibleEntityTypes(ownerSlug);
	const active = visible.find((et) => et.slug === typeScope);

	const selectType = (slug: string) => {
		void navigate(
			memoryEventsFilterSearch(ownerSlug, currentSearch, {
				entity: undefined,
				create: undefined,
				type: slug,
			}),
		);
	};

	const clearType = () => {
		void navigate(
			memoryEventsFilterSearch(ownerSlug, currentSearch, {
				type: undefined,
			}),
		);
	};

	return (
		<Combobox
			contentClassName="w-72"
			searchPlaceholder="Search types..."
			emptyText="No entity types"
			trigger={(open) => (
				<ScopeTrigger open={open} label="Type" value={active?.name} />
			)}
		>
			{(close) => (
				<>
					{typeScope ? (
						<CommandItem
							onSelect={() => {
								clearType();
								close();
							}}
							className="text-muted-foreground"
						>
							Clear type
						</CommandItem>
					) : null}
					{visible.map((et) => (
						<CommandItem
							key={et.id}
							onSelect={() => {
								selectType(et.slug);
								close();
							}}
							className="group gap-2"
						>
							<Check className={cnCheck(et.slug === typeScope)} />
							<EntityIcon icon={et.icon} className="h-4 w-4 shrink-0" />
							<span className="min-w-0 flex-1 truncate">{et.name}</span>
							{typeof et.entity_count === "number" ? (
								<span className="shrink-0 text-xs tabular-nums text-muted-foreground">
									{et.entity_count}
								</span>
							) : null}
							<ManageGear
								to="/$owner/entity-types/$slug"
								params={{ owner: ownerSlug, slug: et.slug }}
								label={et.name}
							/>
						</CommandItem>
					))}
					<CommandItem
						onSelect={() => {
							void navigate(memoryCreateEntityTypeSearch(ownerSlug));
							close();
						}}
						className="text-muted-foreground"
					>
						<Plus className="h-4 w-4 shrink-0" />
						Add entity type
					</CommandItem>
				</>
			)}
		</Combobox>
	);
}

function AgentDropdown({
	ownerSlug,
	agentScope,
}: {
	ownerSlug: string;
	agentScope?: string;
}) {
	const navigate = useNavigate();
	const currentSearch = useMemorySearch();
	const { data: agents = [] } = useAgents();
	const sorted = useMemo(
		() => [...agents].sort((a, b) => a.name.localeCompare(b.name)),
		[agents],
	);
	const active = sorted.find((a) => a.agentId === agentScope);

	const selectAgent = (agentId: string) => {
		void navigate(
			memoryEventsFilterSearch(
				ownerSlug,
				currentSearch,
				agentEventFilterPatch(currentSearch, agentId),
			),
		);
	};

	const clearAgent = () => {
		void navigate(
			memoryEventsFilterSearch(
				ownerSlug,
				currentSearch,
				agentEventFilterPatch(currentSearch, undefined),
			),
		);
	};

	return (
		<Combobox
			contentClassName="w-72"
			searchPlaceholder="Search agents..."
			emptyText="No agents"
			trigger={(open) => (
				<ScopeTrigger open={open} label="Agent" value={active?.name} />
			)}
		>
			{(close) => (
				<>
					{agentScope ? (
						<CommandItem
							onSelect={() => {
								clearAgent();
								close();
							}}
							className="text-muted-foreground"
						>
							Clear agent
						</CommandItem>
					) : null}
					{sorted.map((agent) => (
						<CommandItem
							key={agent.agentId}
							onSelect={() => {
								selectAgent(agent.agentId);
								close();
							}}
							className="gap-2"
						>
							<Check className={cnCheck(agent.agentId === agentScope)} />
							<span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-md bg-muted text-[10px] font-medium">
								{agent.name.trim().charAt(0).toUpperCase() || "?"}
							</span>
							<span className="min-w-0 flex-1 truncate">{agent.name}</span>
						</CommandItem>
					))}
				</>
			)}
		</Combobox>
	);
}

function agentEventFilterPatch(
	currentSearch: Record<string, unknown>,
	agent: string | undefined,
): Record<string, string | undefined> {
	const patch: Record<string, string | undefined> = {
		agent,
		behavior: undefined,
		schedule: undefined,
		platforms: undefined,
	};
	if (currentSearch.schedule != null) {
		patch.run_ids = undefined;
	}
	if (
		typeof currentSearch.platforms === "string" &&
		currentSearch.platforms.trim().length > 0
	) {
		patch.connection_ids = undefined;
		patch.feed_ids = undefined;
	}
	return patch;
}

function ConnectorCascade({
	ownerSlug,
	connectionScope,
	feedScope,
}: {
	ownerSlug: string;
	connectionScope?: string;
	feedScope?: string;
}) {
	const { groups } = useMemoryConnectorGroups();

	const selectedIds = useMemo(
		() =>
			new Set(
				(connectionScope ?? "")
					.split(",")
					.map((s) => s.trim())
					.filter(Boolean),
			),
		[connectionScope],
	);

	// The connector that owns the current connection scope, if the scope is a
	// single connector's connection(s) — drives the Connector trigger label and
	// which connector's connections/feeds the later dropdowns show.
	const scopedConnectorKey = connectorForConnectionIds(groups, selectedIds);
	const scopedGroup = groups.find((g) => g.connector_key === scopedConnectorKey);
	const singleConnectionId =
		selectedIds.size === 1
			? Number([...selectedIds][0])
			: undefined;

	return (
		<>
			<ConnectorDropdown
				ownerSlug={ownerSlug}
				groups={groups}
				scopedGroup={scopedGroup}
			/>
			{scopedGroup ? (
				<ConnectionDropdown
					ownerSlug={ownerSlug}
					group={scopedGroup}
					selectedIds={selectedIds}
				/>
			) : null}
			{singleConnectionId ? (
				<FeedDropdown
					ownerSlug={ownerSlug}
					connectionId={singleConnectionId}
					feedScope={feedScope}
				/>
			) : null}
		</>
	);
}

function ConnectorDropdown({
	ownerSlug,
	groups,
	scopedGroup,
}: {
	ownerSlug: string;
	groups: ReturnType<typeof useMemoryConnectorGroups>["groups"];
	scopedGroup?: ReturnType<
		typeof useMemoryConnectorGroups
	>["groups"][number];
}) {
	const navigate = useNavigate();
	const currentSearch = useMemorySearch();

	const scopeToConnector = (
		group: ReturnType<typeof useMemoryConnectorGroups>["groups"][number],
	) => {
		const ids = group.connections.map((c) => String(c.id)).join(",");
		if (!ids) return;
		void navigate(
			memoryEventsFilterSearch(ownerSlug, currentSearch, {
				connection_ids: ids,
				// Switching connector invalidates any prior feed filter.
				feed_ids: undefined,
			}),
		);
	};

	const clearConnector = () => {
		void navigate(
			memoryEventsFilterSearch(ownerSlug, currentSearch, {
				connection_ids: undefined,
				feed_ids: undefined,
			}),
		);
	};

	const label = scopedGroup?.connector_name ?? scopedGroup?.connector_key;

	return (
		<Combobox
			contentClassName="w-72"
			searchPlaceholder="Search connectors..."
			emptyText="No connectors"
			trigger={(open) => (
				<ScopeTrigger open={open} label="Connector" value={label} />
			)}
		>
			{(close) => (
				<>
					{scopedGroup ? (
						<CommandItem
							onSelect={() => {
								clearConnector();
								close();
							}}
							className="text-muted-foreground"
						>
							Clear connector
						</CommandItem>
					) : null}
					{groups.map((group) => {
						const name = group.connector_name ?? group.connector_key;
						return (
							<CommandItem
								key={group.connector_key}
								disabled={group.connections.length === 0}
								onSelect={() => {
									scopeToConnector(group);
									close();
								}}
								className="group gap-2"
							>
								<Check
									className={cnCheck(
										group.connector_key === scopedGroup?.connector_key,
									)}
								/>
								<ConnectorMark
									plain
									name={name}
									faviconDomain={group.favicon_domain}
									className="h-5 w-5 shrink-0 rounded-md text-[10px]"
								/>
								<span className="min-w-0 flex-1 truncate">{name}</span>
								{group.connection_count > 0 ? (
									<span className="shrink-0 text-xs tabular-nums text-muted-foreground">
										{group.connection_count}
									</span>
								) : null}
								<ManageGear
									to="/$owner/connectors/$connectorKey"
									params={{ owner: ownerSlug, connectorKey: group.connector_key }}
									label={name}
								/>
							</CommandItem>
						);
					})}
					<AddRow
						to="/$owner/connectors/create"
						params={{ owner: ownerSlug }}
						label="Add connector"
						onSelect={close}
					/>
				</>
			)}
		</Combobox>
	);
}

function ConnectionDropdown({
	ownerSlug,
	group,
	selectedIds,
}: {
	ownerSlug: string;
	group: ReturnType<typeof useMemoryConnectorGroups>["groups"][number];
	selectedIds: ReadonlySet<string>;
}) {
	const navigate = useNavigate();
	const currentSearch = useMemorySearch();
	// The label reads the selected connection only when exactly one is scoped;
	// scoping the whole connector selects them all, which the Connector trigger
	// already conveys.
	const single =
		selectedIds.size === 1
			? group.connections.find((c) => selectedIds.has(String(c.id)))
			: undefined;

	const selectConnection = (id: number) => {
		void navigate(
			memoryEventsFilterSearch(ownerSlug, currentSearch, {
				connection_ids: String(id),
				// Narrowing connection drops a feed scoped to a sibling.
				feed_ids: undefined,
			}),
		);
	};

	const label = single
		? connectionLabel({
				display_name: single.display_name,
				connector_name: group.connector_name,
				connector_key: group.connector_key,
			})
		: "All connections";

	return (
		<Combobox
			contentClassName="w-72"
			searchPlaceholder="Search connections..."
			emptyText="No connections"
			trigger={(open) => (
				<ScopeTrigger open={open} label="Connection" value={label} />
			)}
		>
			{(close) =>
				group.connections.map((connection) => {
					const name = connectionLabel({
						display_name: connection.display_name,
						connector_name: group.connector_name,
						connector_key: group.connector_key,
					});
					return (
						<CommandItem
							key={connection.id}
							onSelect={() => {
								selectConnection(connection.id);
								close();
							}}
							className="group gap-2"
						>
							<Check className={cnCheck(selectedIds.has(String(connection.id)))} />
							<span className="min-w-0 flex-1 truncate">{name}</span>
							{connection.feed_count > 0 ? (
								<span className="shrink-0 text-xs tabular-nums text-muted-foreground">
									{connection.feed_count}
								</span>
							) : null}
							<ManageGear
								to="/$owner/connectors/$connectorKey/$connectionId"
								params={{
									owner: ownerSlug,
									connectorKey: group.connector_key,
									connectionId: String(connection.id),
								}}
								label={name}
							/>
						</CommandItem>
					);
				})
			}
		</Combobox>
	);
}

/**
 * The Feed leaf of the cascade. Only rendered once a single connection is
 * scoped, so `useFeeds` fires exactly one query. Events-only: selecting a feed
 * adds a `feed_ids` filter (combining with the connection filter).
 */
function FeedDropdown({
	ownerSlug,
	connectionId,
	feedScope,
}: {
	ownerSlug: string;
	connectionId: number;
	feedScope?: string;
}) {
	const navigate = useNavigate();
	const currentSearch = useMemorySearch();
	const { data: feeds = [], isLoading } = useFeeds(connectionId);
	const selectedIds = useMemo(
		() =>
			new Set(
				(feedScope ?? "")
					.split(",")
					.map((s) => s.trim())
					.filter(Boolean),
			),
		[feedScope],
	);
	const single =
		selectedIds.size === 1
			? feeds.find((f) => selectedIds.has(String(f.id)))
			: undefined;

	const selectFeed = (feed: FeedItem) => {
		void navigate(
			memoryEventsFilterSearch(ownerSlug, currentSearch, {
				connection_ids: String(connectionId),
				feed_ids: String(feed.id),
			}),
		);
	};

	const clearFeed = () => {
		void navigate(
			memoryEventsFilterSearch(ownerSlug, currentSearch, {
				connection_ids: String(connectionId),
				feed_ids: undefined,
			}),
		);
	};

	return (
		<Combobox
			contentClassName="w-72"
			searchPlaceholder="Search feeds..."
			emptyText={isLoading ? "Loading feeds..." : "No feeds"}
			trigger={(open) => (
				<ScopeTrigger
					open={open}
					label="Feed"
					value={single ? feedLabel(single) : undefined}
				/>
			)}
		>
			{(close) => (
				<>
					{selectedIds.size > 0 ? (
						<CommandItem
							onSelect={() => {
								clearFeed();
								close();
							}}
							className="text-muted-foreground"
						>
							Clear feed
						</CommandItem>
					) : null}
					{feeds.map((feed) => (
						<CommandItem
							key={feed.id}
							onSelect={() => {
								selectFeed(feed);
								close();
							}}
							className="gap-2"
						>
							<Check className={cnCheck(selectedIds.has(String(feed.id)))} />
							<span className="min-w-0 flex-1 truncate">{feedLabel(feed)}</span>
						</CommandItem>
					))}
				</>
			)}
		</Combobox>
	);
}

function feedLabel(feed: FeedItem): string {
	return feed.display_name?.trim() || feed.feed_key;
}

/**
 * The hover-reveal "Manage <x>" gear inside a dropdown row. Unlike the rail's
 * `MemoryRailSettingsLink`, this lives inside a selectable `cmdk` item, so it
 * stops propagation: clicking the gear navigates to the settings route without
 * also firing the row's `onSelect` (which would scope + close the popover).
 */
function ManageGear({
	to,
	params,
	label,
}: {
	to: string;
	params: Record<string, string>;
	label: string;
}) {
	return (
		<Link
			to={to}
			params={params}
			onClick={(e) => e.stopPropagation()}
			onPointerDown={(e) => e.stopPropagation()}
			className="shrink-0 rounded-md p-1 text-muted-foreground opacity-0 transition-opacity hover:text-foreground group-hover:opacity-100 focus-visible:opacity-100"
			aria-label={`Manage ${label}`}
		>
			<Settings2 className="h-3.5 w-3.5" />
		</Link>
	);
}

function AddRow({
	to,
	params,
	label,
	onSelect,
}: {
	to: "/$owner/entity-types/new" | "/$owner/connectors/create";
	params: { owner: string };
	label: string;
	onSelect: () => void;
}) {
	return (
		<CommandItem asChild onSelect={onSelect} className="text-muted-foreground">
			<Link to={to} params={params} className="flex items-center gap-2">
				<Plus className="h-4 w-4 shrink-0" />
				{label}
			</Link>
		</CommandItem>
	);
}

function cnCheck(selected: boolean): string {
	return selected
		? "h-4 w-4 shrink-0 opacity-100"
		: "h-4 w-4 shrink-0 opacity-0";
}

