1	import { createFileRoute, notFound, redirect } from "@tanstack/react-router";
2	import { parseMemorySplat } from "@/lib/memory-browse";
3	import { isReservedOwnerSegment } from "@/lib/reserved";
4	import {
5		decodeEntityBrowsePath,
6		decodeEntityTypeParam,
7	} from "@/lib/url";
8	
9	/**
10	 * Legacy / deep-link path form. Everything memory-related is now an in-place
11	 * scope on `/memory` (the tab bar never disappears), so this route only
12	 * redirects: a bare `/memory/<type>` → `?type=<slug>`, an entity path
13	 * `/memory/<type>/<slug>[/…]` → `?entity=<path>`.
14	 */
15	export const Route = createFileRoute("/$owner/memory/$")({
16		beforeLoad: ({ params }) => {
17			const splat = parseMemorySplat(params._splat || "");
18			if (!splat.typeSegment) {
19				throw redirect({
20					to: "/$owner/memory",
21					params: { owner: params.owner },
22					search: {},
23					replace: true,
24				});
25			}
26			if (isReservedOwnerSegment(splat.typeSegment)) {
27				throw notFound();
