import { createFileRoute, notFound, redirect } from "@tanstack/react-router";
import { parseMemorySplat } from "@/lib/memory-browse";
import { isReservedOwnerSegment } from "@/lib/reserved";
import {
	decodeEntityBrowsePath,
	decodeEntityTypeParam,
} from "@/lib/url";

/**
 * Legacy / deep-link path form. Everything memory-related is now an in-place
 * scope on `/memory` (the tab bar never disappears), so this route only
 * redirects: a bare `/memory/<type>` → `?type=<slug>`, an entity path
 * `/memory/<type>/<slug>[/…]` → `?entity=<path>`.
 */
export const Route = createFileRoute("/$owner/memory/$")({
	beforeLoad: ({ params }) => {
		const splat = parseMemorySplat(params._splat || "");
		if (!splat.typeSegment) {
			throw redirect({
				to: "/$owner/memory",
				params: { owner: params.owner },
				search: {},
				replace: true,
			});
		}
		if (isReservedOwnerSegment(splat.typeSegment)) {
			throw notFound();
		}
		throw redirect({
			to: "/$owner/memory",
			params: { owner: params.owner },
			// One scope at a time: an entity path → ?entity= only (its type is
			// derived); a bare type → ?type=.
			search: splat.isEntityDetail
				? {
						entity: splat.path
							? decodeEntityBrowsePath(splat.path)
							: undefined,
					}
				: {
						type: splat.typeSegment
							? decodeEntityTypeParam(splat.typeSegment)
							: undefined,
					},
			replace: true,
		});
	},
	component: () => null,
});

