import { Link } from "@tanstack/react-router";
import { Search } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
	Tooltip,
	TooltipContent,
	TooltipTrigger,
} from "@/components/ui/tooltip";
import {
	memoryConnectionDrillSearch,
	memoryFeedDrillSearch,
} from "@/lib/memory-browse";
import { cn } from "@/lib/utils";

type Scope =
	| { kind: "connection"; id: number }
	| { kind: "feed"; id: number }
	| { kind: "run"; id: number };

function scopeToMemoryLink(ownerSlug: string, scope: Scope) {
	switch (scope.kind) {
		case "connection":
			return memoryConnectionDrillSearch(ownerSlug, scope.id);
		case "feed":
			return memoryFeedDrillSearch(ownerSlug, scope.id);
		case "run":
			return {
				to: "/$owner/memory" as const,
				params: { owner: ownerSlug },
				search: { view: "events" as const, run_ids: String(scope.id) },
			};
	}
}

export function ViewInMemoryLink({
	ownerSlug,
	scope,
	variant = "outline",
	iconOnly = false,
	label,
	className,
	title,
}: {
	ownerSlug: string;
	scope: Scope;
	variant?: "outline" | "ghost" | "default";
	iconOnly?: boolean;
	label?: string;
	className?: string;
	title?: string;
}) {
	const link = scopeToMemoryLink(ownerSlug, scope);
	const tooltipLabel = title ?? label ?? "View in memory";
	const button = (
		<Button
			asChild
			variant={variant}
			size={iconOnly ? "icon" : "sm"}
			className={cn(iconOnly && "h-7 w-7", className)}
		>
			<Link to={link.to} params={link.params} search={link.search}>
				<Search className={cn("h-3.5 w-3.5", !iconOnly && "mr-1.5")} />
				{!iconOnly && (label ?? "View in memory")}
			</Link>
		</Button>
	);
	if (!iconOnly) return button;
	return (
		<Tooltip>
			<TooltipTrigger asChild>{button}</TooltipTrigger>
			<TooltipContent>{tooltipLabel}</TooltipContent>
		</Tooltip>
	);
}

