155	export function EventsTab({
156		organizationId,
157		ownerSlug,
158		entityId,
159		hideSourceFilter = false,
160		scopedEntityTypes,
161	}: EventsTabProps) {
162		const { isAuthenticated, isReady } = useAuthState();
163		const { isMember, isLoading: isOrgLoading } = useCurrentOrg();
164		const canManageWorkspace = isReady && isAuthenticated && isMember;
165		const canReadPublicWorkspace =
166			isReady && (!isAuthenticated || (!isOrgLoading && !isMember));
167	
168		const navigate = useNavigate();
169		const location = useLocation();
170		const scheduleScopeId = parseScheduleScope(location.search ?? {});
171	
172		const {
173			filters: urlFilters,
174			updateFilters: updateUrlFilters,
175			clearFilters: clearUrlFilters,
176		} = useTabFilters<PartialEventFilters>({
177			parse: parseEventFiltersFromUrl,
178			serialize: serializeEventFiltersToSearch,
179			filterKeys: EVENT_FILTER_KEYS,
180			merge: mergeEventTabFilters,
181		});
182	
183		// Local search state (for debouncing)
184		const [searchQuery, setSearchQuery] = useState(urlFilters.searchQuery || "");
185		const debouncedSearch = useDebounce(searchQuery, 1000);
186	
187		// Combine URL filters with debounced search
188		const filters = useMemo<PartialEventFilters>(
189			() =>
190				applyEventTabDefaults({
191					...urlFilters,
192					searchQuery: debouncedSearch.length >= 3 ? debouncedSearch : undefined,
193					...(scopedEntityTypes?.length
194						? { entityTypes: scopedEntityTypes }
195						: {}),
196				}),
197			[urlFilters, debouncedSearch, scopedEntityTypes],
198		);
199	
200		const updateFilters = updateUrlFilters;
201	
202		useEffect(() => {
203			const normalizedSearch =
204				debouncedSearch.length >= 3 ? debouncedSearch : undefined;
205			if ((urlFilters.searchQuery || undefined) === normalizedSearch) {
206				return;
207			}
208			updateUrlFilters({ searchQuery: normalizedSearch });
209		}, [debouncedSearch, updateUrlFilters, urlFilters.searchQuery]);
210	
211		const clearFilters = () => {
212			setSearchQuery("");
213			clearUrlFilters();
214		};
215	
216		const hasFilters = useMemo(
217			() =>
218				checkActiveFilters(
219					applyEventTabDefaults({
220						...urlFilters,
221						searchQuery:
222							debouncedSearch.length >= 3 ? debouncedSearch : undefined,
223					}),
224				),
225			[urlFilters, debouncedSearch],
226		);
227	
228		// Entity scope comes from either the prop (when embedded as an entity tab) or
229		// the URL drill-down filter — the entity page's "See memory" deep-links into
230		// the org-wide Memory page with ?entity_id=…. Both paths scope identically.
231		const effectiveEntityId = entityId ?? filters.entityId ?? undefined;
232		const isOrgWide = effectiveEntityId === undefined;
233	
234		// Fetch data — gate every auth/public fork on `isReady` so the bootstrap
