/**
 * Canonical single-scope search used for legacy URLs and encoded entity/type
 * normalization. Additive Events filters are left intact by the redirect guard.
 */
export function canonicalMemorySearch(
	search: Record<string, unknown>,
): Record<string, string | undefined> {
	const entity = parseEntityScope(search);

	const type =
		typeof search.type === "string" && search.type.trim()
			? decodeEntityTypeParam(search.type.trim())
			: undefined;
	const view = pickMemoryView(search);
	const create = pickMemoryCreate(search);
	const connectionIds = parseConnectionScope(search);
	const agentId = pickAgentScope(search);
	const runIds = pickRunScope(search);
	const peekSearch = pickPeekSearch(search);

	if (entity) {
		return { ...pruneSearch({ view, entity, create }), ...peekSearch };
	}
	if (type) {
		return { ...pruneSearch({ view, type, create }), ...peekSearch };
	}
	if (connectionIds) {
		return {
			...pruneSearch({ view, connection_ids: connectionIds }),
			...peekSearch,
		};
	}
	if (agentId) {
		const watcher = pickWatcherScope(search);
		const schedule = pickScheduleScope(search);
		const platforms =
			typeof search.platforms === "string" && search.platforms.trim()
				? search.platforms.trim()
				: undefined;
		return {
			...pruneSearch({
				view,
				agent: agentId,
				behavior: watcher,
				schedule,
				platforms,
				run_ids: runIds,
			}),
			...peekSearch,
		};
	}
	return {
		...pruneSearch({ view, create, run_ids: runIds }),
		...peekSearch,
	};
}

