import { Activity, Boxes, type LucideIcon, Plug } from "lucide-react";

/**
 * Owner-scoped nav sections — one icon + label shared by sidebar and page
 * headers. The sidebar is the site map: sections render in this order.
 *
 * Memory is two destinations, not one page with tabs:
 *  - **Activity** → Events stream (`/memory`, default view)
 *  - **Context** → entity types/records (`/memory?view=entities`)
 * The Events/Entities tab strip on the Memory page is gone — the sidebar is
 * the switch. Connect is connectors + synthesized providers/sandboxes.
 */
export const OWNER_SECTIONS = {
	activity: {
		icon: Activity,
		label: "Activity",
		/** Router template. */
		to: "/$owner/memory",
		/**
		 * Events is the default Memory view — omit `view` so the URL stays clean.
		 * Active when the user is on `/memory` without an entities view/scope.
		 */
		search: {} as Record<string, unknown>,
		/** Path segment under `/$owner/` used for coarse matching. */
		segment: "memory",
		/** Which Memory view this row represents. */
		memoryView: "events" as const,
	},
	connectors: {
		icon: Plug,
		label: "Connect",
		to: "/$owner/connectors",
		search: {} as Record<string, unknown>,
		segment: "connectors",
		memoryView: null,
	},
	context: {
		icon: Boxes,
		label: "Context",
		to: "/$owner/memory",
		search: { view: "entities" } as Record<string, unknown>,
		segment: "memory",
		memoryView: "entities" as const,
	},
} as const satisfies Record<
	string,
	{
		icon: LucideIcon;
		label: string;
		to: string;
		search: Record<string, unknown>;
		segment: string;
		memoryView: "events" | "entities" | null;
	}
>;

export type OwnerSectionKey = keyof typeof OWNER_SECTIONS;

/**
 * Whether a sidebar section is active for the current path + search.
 * Activity and Context share `/memory`; the active one is decided by the
 * Memory view (and by entity-shaped scopes / splat paths for Context).
 */
export function isOwnerSectionActive(
	key: OwnerSectionKey,
	owner: string,
	pathname: string,
	search: Record<string, unknown>,
): boolean {
	const section = OWNER_SECTIONS[key];
	const base = `/${owner}/${section.segment}`;
	const onSegment =
		pathname === base ||
		pathname === `${base}/` ||
		pathname.startsWith(`${base}/`);

	if (!onSegment) return false;

	if (section.memoryView == null) {
		// Connect (and any future non-memory section): any path under the segment.
		return true;
	}

	// Entity detail / type splat under /memory/* is always the Context surface.
	const isSplat = pathname !== base && pathname !== `${base}/`;
	if (isSplat) return section.memoryView === "entities";

	const view = search.view;
	const hasEntityScope =
		typeof search.type === "string" ||
		typeof search.entity === "string" ||
		search.create_type === true ||
		search.create_type === "true";

	// Mirror resolveMemoryView: explicit view wins; type/entity scope implies
	// entities; bare /memory is events.
	const resolved: "events" | "entities" =
		view === "entities"
			? "entities"
			: view === "events" || view === "feeds"
				? "events"
				: hasEntityScope
					? "entities"
					: "events";

	return section.memoryView === resolved;
}

