	ownerSlug,
	typeScope,
	entityScope,
	create,
	createType = false,
}: {
	ownerSlug: string;
	typeScope?: string;
	entityScope?: string;
	create: boolean;
	/** Create-entity-type subpage. */
	createType?: boolean;
}) {
	const navigate = useNavigate();
	const { orgContext } = useOrgContext();
	const typeSlug = typeScope ? decodeEntityTypeParam(typeScope) : undefined;
	const isMemberScope =
		typeSlug === "$member" || entityScope?.split("/")[0] === "$member";

	// Resolve the selected entity (if any) to its id + type for the detail render.
	const {
		data: resolved,
		isLoading: entityLoading,
		error: entityError,
	} = useResolvedPath(
		entityScope ? `/${ownerSlug}/${decodeEntityBrowsePath(entityScope)}` : "",
		orgContext,
	);
