		const legacyDetail =
			typeof s.browse_path === "string" && s.browse_path.trim()
				? s.browse_path.trim()
				: undefined;
		if (legacyDetail) {
			throw redirect({
				to: "/$owner/memory/$",
				params: { owner: params.owner, _splat: legacyDetail },
				search: {},
				replace: true,
			});
		}
		const legacyType =
			typeof s.browse_type === "string" && s.browse_type.trim()
				? s.browse_type.trim()
				: undefined;
		if (legacyType) {
			throw redirect({
				to: "/$owner/memory",
				params: { owner: params.owner },
