	validateSearch: (search: Record<string, unknown>) => {
		const result = pruneSearch(search) as Record<string, string | undefined>;
		// `stringifyRouterSearch` JSON-parses primitive search values, so `?create=true`
		// round-trips as boolean `true` — normalize back to the string the UI reads.
		if (search.create === true || search.create === "true") {
			result.create = "true";
		}
		// Create-entity-type subpage.
