export const PEEK_SEARCH_KEYS = [
	"peek",
	"peek_run_id",
	"peek_agent",
	"peek_behavior",
	"peek_behavior_run_id",
	"peek_view",
] as const;

export type PeekSearchKey = (typeof PEEK_SEARCH_KEYS)[number];
export type PeekSearch = Partial<Record<PeekSearchKey, string>>;

function isPeekOpenFlag(value: unknown): boolean {
	return value === "1" || value === "true" || value === true || value === 1;
}

export function pickPeekSearch(
	search: Record<string, unknown> | undefined | null,
): PeekSearch {
	if (!search) return {};
	const out: PeekSearch = {};
	for (const key of PEEK_SEARCH_KEYS) {
		const value = search[key];
		if (value == null || value === "") continue;
		if (key === "peek") {
			if (isPeekOpenFlag(value)) out.peek = "1";
			continue;
		}
		if (typeof value === "string" && value.trim()) {
			out[key] = value.trim();
		} else if (typeof value === "number" && Number.isFinite(value)) {
			out[key] = String(value);
		}
	}
	return out;
}

export function omitPeekSearch<T extends Record<string, unknown>>(
	search: T,
): Omit<T, PeekSearchKey> {
	const next = { ...search };
	for (const key of PEEK_SEARCH_KEYS) delete next[key];
	return next as Omit<T, PeekSearchKey>;
}

