import { Link, useLocation } from "@tanstack/react-router";
import { Plus } from "lucide-react";
import { useMemo } from "react";
import { MemoryRailSettingsLink } from "@/components/memory/memory-rail-settings-link";
import { useVisibleEntityTypes } from "@/components/memory/use-visible-entity-types";
import { EntityIcon } from "@/components/ui/entity-icon";
import { Skeleton } from "@/components/ui/skeleton";
import { useOrgContext } from "@/hooks/use-org-context";
import { useResolvedPath } from "@/lib/api";
import {
	MEMORY_RAIL_ROW_ACTIVE,
	MEMORY_RAIL_ROW_IDLE,
	memoryBrowseTypeSearch,
	parseEntityScope,
} from "@/lib/memory-browse";
import { decodeEntityBrowsePath, decodeEntityTypeParam } from "@/lib/url";
import { cn } from "@/lib/utils";

type EntityTypeRailProps = {
	ownerSlug: string;
	isLoading?: boolean;
} & ({ mode: "filter" } | { mode: "browse"; activeEntityTypeSlug: string });

/**
 * The active entity-type slug. On the memory home it's the in-place `?type=`
 * scope; on an entity-detail page (`/{owner}/memory/{type}/{slug}/...`) it's the
 * first path segment. Returns undefined when nothing is scoped.
 */
function activeTypeFromLocation(
	pathname: string,
	search: Record<string, unknown>,
	ownerSlug: string,
): string | undefined {
	const detailPrefix = `/${ownerSlug}/memory/`;
	if (pathname.startsWith(detailPrefix)) {
		const first = pathname.slice(detailPrefix.length).split("/")[0];
		if (first) return decodeEntityTypeParam(first);
	}
	const typeScope = search.type;
	return typeof typeScope === "string" && typeScope.trim()
		? decodeEntityTypeParam(typeScope.trim())
		: undefined;
}

function EntityTypeRailSkeleton() {
	return (
		<div className="flex w-full flex-col gap-2">
			<Skeleton className="h-8 w-full rounded-lg" />
			<Skeleton className="h-10 w-full rounded-lg" />
			<Skeleton className="h-10 w-full rounded-lg" />
			<Skeleton className="h-10 w-full rounded-lg" />
		</div>
	);
}

/**
 * Navigation rail listing the workspace's entity types. Clicking a type browses
 * it (its entity list). Hover reveals a settings gear → entity type schema page
 * (same pattern as the Connectors rail). The active type comes from `?type=`
 * (Memory home) or the route path (entity detail); filter-mode links preserve
 * the current search.
 */
export function EntityTypeRail(props: EntityTypeRailProps) {
	const { ownerSlug, isLoading } = props;
	const { visible, isTypesLoading } = useVisibleEntityTypes(ownerSlug);
	const { orgContext } = useOrgContext();
	const location = useLocation();

	const activeSlug = useMemo(() => {
		if (props.mode === "browse") {
			return decodeEntityTypeParam(props.activeEntityTypeSlug);
		}
		return activeTypeFromLocation(
			location.pathname,
			location.search ?? {},
			ownerSlug,
		);
	}, [props, location.pathname, location.search, ownerSlug]);

	// The selected entity (`?entity=<type>/<slug>`) is shown as a sub-row under
	// its type, so the sidebar carries the "where am I" context (no breadcrumb).
	const entityScope =
		props.mode === "filter"
			? parseEntityScope(location.search ?? {})
			: undefined;
	const { data: resolvedEntity } = useResolvedPath(
		entityScope
			? `/${ownerSlug}/${decodeEntityBrowsePath(entityScope)}`
			: "",
		orgContext,
	);
	const selectedEntity = entityScope ? resolvedEntity?.entity : undefined;

	if (isLoading || isTypesLoading) {
		return <EntityTypeRailSkeleton />;
	}

	return (
		<nav aria-label="Entity types" className="flex w-full flex-col gap-1">
			<div className="px-1 pb-1">
				<span className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
					Entity types
				</span>
			</div>

			<ul className="flex flex-col gap-0.5">
				{visible.map((et) => {
					const isActive = et.slug === activeSlug;
					const link = memoryBrowseTypeSearch(
						ownerSlug,
						et.slug,
						location.search ?? {},
					);
					const entityUnderType =
						selectedEntity && selectedEntity.entity_type === et.slug
							? selectedEntity
							: undefined;
					return (
						<li key={et.id} className="flex flex-col gap-0.5">
							<div
								className={cn(
									"group flex items-center gap-1 rounded-lg px-1 transition-colors",
									isActive ? MEMORY_RAIL_ROW_ACTIVE : MEMORY_RAIL_ROW_IDLE,
								)}
							>
								<Link
									to={link.to}
									params={link.params}
									search={link.search}
									className="flex min-w-0 flex-1 items-center gap-2 rounded-md px-1 py-2 text-sm"
									aria-current={isActive ? "page" : undefined}
								>
									<EntityIcon icon={et.icon} className="h-4 w-4 shrink-0" />
									<span className="min-w-0 flex-1 truncate font-medium">
										{et.name}
									</span>
									{typeof et.entity_count === "number" ? (
										<span className="shrink-0 text-xs tabular-nums text-muted-foreground">
											{et.entity_count}
										</span>
									) : null}
								</Link>
								<MemoryRailSettingsLink
									to="/$owner/entity-types/$slug"
									params={{ owner: ownerSlug, slug: et.slug }}
									label={et.name}
								/>
							</div>
							{entityUnderType ? (
								<div className="ml-3 border-l border-border pl-2 pt-0.5">
									<span
										className={cn(
											"flex items-center gap-2 rounded-lg px-2 py-1.5 text-sm",
											MEMORY_RAIL_ROW_ACTIVE,
										)}
										aria-current="page"
									>
										<span className="min-w-0 flex-1 truncate font-medium">
											{entityUnderType.name}
										</span>
									</span>
								</div>
							) : null}
						</li>
					);
				})}
			</ul>

			<AddEntityTypeLink ownerSlug={ownerSlug} />
		</nav>
	);
}

function AddEntityTypeLink({ ownerSlug }: { ownerSlug: string }) {
	return (
		<Link
			to="/$owner/memory"
			params={{ owner: ownerSlug }}
			search={{ view: "entities", create_type: "true" }}
			className="mt-2 flex items-center gap-2 rounded-lg px-2 py-2 text-sm text-muted-foreground transition-colors hover:bg-muted/40 hover:text-foreground"
		>
			<Plus className="h-4 w-4 shrink-0" />
			Add entity type
		</Link>
	);
}

