111							selectedEntity && selectedEntity.entity_type === et.slug
112								? selectedEntity
113								: undefined;
114						return (
115							<li key={et.id} className="flex flex-col gap-0.5">
116								<div
117									className={cn(
118										"group flex items-center gap-1 rounded-lg px-1 transition-colors",
119										isActive ? MEMORY_RAIL_ROW_ACTIVE : MEMORY_RAIL_ROW_IDLE,
120									)}
121								>
122									<Link
123										to={link.to}
124										params={link.params}
125										search={link.search}
126										className="flex min-w-0 flex-1 items-center gap-2 rounded-md px-1 py-2 text-sm"
127										aria-current={isActive ? "page" : undefined}
128									>
129										<EntityIcon icon={et.icon} className="h-4 w-4 shrink-0" />
130										<span className="min-w-0 flex-1 truncate font-medium">
131											{et.name}
132										</span>
133										{typeof et.entity_count === "number" ? (
134											<span className="shrink-0 text-xs tabular-nums text-muted-foreground">
135												{et.entity_count}
136											</span>
137										) : null}
138									</Link>
139									<MemoryRailSettingsLink
140										to="/$owner/entity-types/$slug"
141										params={{ owner: ownerSlug, slug: et.slug }}
142										label={et.name}
143									/>
144								</div>
145								{entityUnderType ? (
146									<div className="ml-3 border-l border-border pl-2 pt-0.5">
147										<span
148											className={cn(
149												"flex items-center gap-2 rounded-lg px-2 py-1.5 text-sm",
150												MEMORY_RAIL_ROW_ACTIVE,
151											)}
152											aria-current="page"
153										>
154											<span className="min-w-0 flex-1 truncate font-medium">
155												{entityUnderType.name}
156											</span>
157										</span>
158									</div>
159								) : null}
160							</li>
161						);
162					})}
163				</ul>
164	
165				<AddEntityTypeLink ownerSlug={ownerSlug} />
166			</nav>
167		);
168	}
169	
170	function AddEntityTypeLink({ ownerSlug }: { ownerSlug: string }) {
171		return (
172			<Link
173				to="/$owner/memory"
174				params={{ owner: ownerSlug }}
175				search={{ create_type: "true" }}
176				className="mt-2 flex items-center gap-2 rounded-lg px-2 py-2 text-sm text-muted-foreground transition-colors hover:bg-muted/40 hover:text-foreground"
177			>
178				<Plus className="h-4 w-4 shrink-0" />
179				Add entity type
180			</Link>
181		);
182	}

