import { describe, expect, it } from "vitest";
import {
	buildMemoryEntityScopePath,
	canonicalMemorySearch,
	connectorForConnectionIds,
	entityPathToBrowsePath,
	memoryBrowseEntitySearch,
	memoryBrowseHomeSearch,
	memoryBrowseTypeSearch,
	memoryEventsFilterSearch,
	memoryFeedDrillSearch,
	memoryMemberListSearch,
	memoryScopeSearch,
	memorySearchNeedsCanonicalRedirect,
	memoryWatcherDrillSearch,
	parseConnectionScope,
	parseEntityScope,
	parseMemorySplat,
	parseMemoryView,
	resolveMemoryView,
} from "./memory-browse";

describe("parseMemoryView", () => {
	it("returns null when unset or unrecognized", () => {
		expect(parseMemoryView(undefined)).toBeNull();
		expect(parseMemoryView("nonsense")).toBeNull();
		expect(parseMemoryView("records")).toBeNull();
	});

	it("recognizes Events and Entities; maps removed Feeds to Events", () => {
		expect(parseMemoryView("events")).toBe("events");
		expect(parseMemoryView("feeds")).toBe("events");
		expect(parseMemoryView("entities")).toBe("entities");
	});
});

describe("resolveMemoryView", () => {
	it("defaults to events unscoped, entities when a type is scoped", () => {
		expect(resolveMemoryView(undefined, false)).toBe("events");
		expect(resolveMemoryView(undefined, true)).toBe("entities");
	});

	it("honors an explicit view regardless of scope", () => {
		expect(resolveMemoryView("feeds", true)).toBe("events");
		expect(resolveMemoryView("events", true)).toBe("events");
		expect(resolveMemoryView("entities", false)).toBe("entities");
	});
});

describe("parseMemorySplat", () => {
	it("parses an empty splat as the events home", () => {
		expect(parseMemorySplat("")).toEqual({ isEntityDetail: false });
		expect(parseMemorySplat(undefined)).toEqual({ isEntityDetail: false });
	});

	it("parses a bare type segment (entity list)", () => {
		expect(parseMemorySplat("company")).toEqual({
			typeSegment: "company",
			path: "company",
			isEntityDetail: false,
		});
	});

	it("parses a type/slug path as entity detail", () => {
		expect(parseMemorySplat("company/acme-corp")).toEqual({
			typeSegment: "company",
			path: "company/acme-corp",
			isEntityDetail: true,
		});
	});

	it("strips surrounding slashes", () => {
		expect(parseMemorySplat("/person/alice/")).toEqual({
			typeSegment: "person",
			path: "person/alice",
			isEntityDetail: true,
		});
	});
});

describe("memory scope link builders", () => {
	it("scopes a type in place via ?type, clearing other scopes", () => {
		expect(
			memoryBrowseTypeSearch("acme", "person", {
				connection_ids: "1",
				entity: "company/acme-corp",
			}),
		).toEqual({
			to: "/$owner/memory",
			params: { owner: "acme" },
			search: { type: "person" },
		});
	});

	it("preserves the current view when picking a type scope", () => {
		expect(
			memoryBrowseTypeSearch("acme", "person", { view: "events" }).search,
		).toEqual({ type: "person", view: "events" });
	});

	it("scopes a single entity via ?entity, clearing the type scope", () => {
		expect(
			memoryBrowseEntitySearch(
				"acme",
				[{ entity_type: "person", slug: "alice" }],
				{ type: "company", view: "events" },
			),
		).toEqual({
			to: "/$owner/memory",
			params: { owner: "acme" },
			search: { entity: "person/alice", view: "events" },
		});
	});

	it("scopes a connector via ?connection_ids, clearing type + entity", () => {
		expect(
			memoryScopeSearch(
				"acme",
				{ kind: "connection", ids: "3,7" },
				{ type: "company", entity: "company/acme-corp", view: "events" },
			).search,
		).toEqual({ connection_ids: "3,7", view: "events" });
	});

	it("scopes an agent via ?agent, clearing type + entity + connector", () => {
		expect(
			memoryScopeSearch(
				"acme",
				{ kind: "agent", id: "crm" },
				{
					type: "company",
					entity: "company/acme-corp",
					connection_ids: "3",
					view: "events",
				},
			).search,
		).toEqual({ agent: "crm", view: "events" });
	});

	it("drills from a watch behavior into Events scoped to that watcher", () => {
		expect(memoryWatcherDrillSearch("acme", "crm", "42")).toEqual({
			to: "/$owner/memory",
			params: { owner: "acme" },
			search: { agent: "crm", behavior: "42", view: "events" },
		});
	});

	it("drills connector feeds into Events", () => {
		expect(memoryFeedDrillSearch("acme", 7, { connectionScope: "3" })).toEqual({
			to: "/$owner/memory",
			params: { owner: "acme" },
			search: { view: "events", feed_ids: "7", connection_ids: "3" },
		});
	});

	it("applies a view override (connector on the Entity view → Events)", () => {
		expect(
			memoryScopeSearch(
				"acme",
				{ kind: "connection", ids: "3" },
				{ view: "entities" },
				"events",
			).search,
		).toEqual({ connection_ids: "3", view: "events" });
	});

	it("formats entity path segments for search (literal $ in type slugs)", () => {
		expect(
			entityPathToBrowsePath([
				{ entity_type: "person", slug: "alice" },
				{ entity_type: "project", slug: "lobu" },
			]),
		).toBe("person/alice/project/lobu");
		expect(
			entityPathToBrowsePath([{ entity_type: "$member", slug: "alice" }]),
		).toBe("$member/alice");
	});

	it("scopes $member via ?type= without pre-encoding %24", () => {
		expect(memoryBrowseTypeSearch("acme", "$member").search).toEqual({
			type: "$member",
		});
	});

	it("normalizes a double-encoded entity scope on read", () => {
		expect(
			parseEntityScope({ entity: "%24member/alice" }),
		).toBe("$member/alice");
	});

	it("clears every scope + drill-down on the home link, keeping the view", () => {
		expect(
			memoryBrowseHomeSearch({
				type: "company",
				entity: "company/acme-corp",
				connection_ids: "1",
				feed_ids: "2",
				view: "events",
			}).search,
		).toEqual({ view: "events" });
	});
});

describe("canonicalMemorySearch", () => {
	it("decodes pre-encoded member entity scopes", () => {
		expect(
			canonicalMemorySearch({
				entity: "%24member/acme",
				view: "entities",
			}),
		).toEqual({ entity: "$member/acme" });
	});

	it("decodes pre-encoded type slugs", () => {
		expect(canonicalMemorySearch({ type: "%24member" })).toEqual({
			type: "$member",
		});
	});

	it("drops type when an entity scope is present", () => {
		expect(
			canonicalMemorySearch({
				type: "person",
				entity: "person/alice",
			}),
		).toEqual({ entity: "person/alice" });
	});

	it("preserves a bare run-scoped approval permalink", () => {
		expect(
			canonicalMemorySearch({
				view: "events",
				run_ids: "610840",
			}),
		).toEqual({ view: "events", run_ids: "610840" });
	});

	it("normalizes numeric run ids parsed from direct URLs", () => {
		expect(canonicalMemorySearch({ run_ids: 610840 })).toEqual({
			run_ids: "610840",
		});
	});

	it("preserves namespaced peek state alongside route filters", () => {
		expect(
			canonicalMemorySearch({
				type: "person",
				peek: "1",
				peek_run_id: "42",
			}),
		).toEqual({ type: "person", peek: "1", peek_run_id: "42" });
	});
});

describe("memorySearchNeedsCanonicalRedirect", () => {
	it("flags double-encoded entity scopes", () => {
		expect(
			memorySearchNeedsCanonicalRedirect({
				entity: "%24member/alice",
			}),
		).toEqual({ entity: "$member/alice" });
	});

	it("flags stale type+entity pairs", () => {
		expect(
			memorySearchNeedsCanonicalRedirect({
				type: "$member",
				entity: "$member/alice",
			}),
		).toEqual({ entity: "$member/alice" });
	});

	it("is a no-op for already-canonical member list URLs", () => {
		expect(
			memorySearchNeedsCanonicalRedirect({
				type: "$member",
				view: "entities",
			}),
		).toBeNull();
	});

	it("preserves create=true through canonicalization", () => {
		expect(
			canonicalMemorySearch({
				type: "$member",
				view: "entities",
				create: true,
			}),
		).toEqual({ type: "$member", create: "true" });
	});

	it("does not redirect a combined Events URL", () => {
		expect(
			memorySearchNeedsCanonicalRedirect({
				view: "events",
				type: "company",
				connection_ids: "1",
				agent: "scout",
			}),
		).toBeNull();
	});
});

describe("memoryMemberListSearch", () => {
	it("scopes the built-in members list on memory", () => {
		expect(memoryMemberListSearch("acme")).toEqual({
			to: "/$owner/memory",
			params: { owner: "acme" },
			search: { type: "$member", view: "entities" },
		});
	});
});

describe("buildMemoryEntityScopePath", () => {
	it("builds a memory entity detail URL for refs and callbacks", () => {
		expect(
			buildMemoryEntityScopePath("acme", [
				{ entity_type: "$member", slug: "alice" },
			]),
		).toBe("/acme/memory?entity=%24member%2Falice&view=entities");
	});
});

describe("memoryEventsFilterSearch", () => {
	it("adds a filter key while preserving sibling event filters", () => {
		const link = memoryEventsFilterSearch(
			"acme",
			{ view: "events", type: "company", connection_ids: "1" },
			{ agent: "scout" },
		);
		expect(link.to).toBe("/$owner/memory");
		expect(link.params).toEqual({ owner: "acme" });
		// The pre-existing type + connection_ids survive; agent is added.
		expect(link.search).toEqual({
			view: "events",
			type: "company",
			connection_ids: "1",
			agent: "scout",
		});
	});

	it("clears exactly one key when its patch value is undefined", () => {
		const link = memoryEventsFilterSearch(
			"acme",
			{ view: "events", type: "company", connection_ids: "1", feed_ids: "9" },
			{ feed_ids: undefined },
		);
		expect(link.search).toEqual({
			view: "events",
			type: "company",
			connection_ids: "1",
		});
	});

	it("always forces the events view", () => {
		const link = memoryEventsFilterSearch("acme", { view: "feeds" }, {
			connection_ids: "1",
		});
		expect(link.search.view).toBe("events");
	});
});

describe("connectorForConnectionIds", () => {
	const groups = [
		{ connector_key: "slack", connections: [{ id: 1 }, { id: 2 }] },
		{ connector_key: "gmail", connections: [{ id: 3 }] },
	];

	it("returns the owning connector for a single connection", () => {
		expect(connectorForConnectionIds(groups, new Set(["3"]))).toBe("gmail");
	});

	it("returns the connector when all ids belong to one connector", () => {
		expect(connectorForConnectionIds(groups, new Set(["1", "2"]))).toBe(
			"slack",
		);
	});

	it("returns undefined when ids span more than one connector", () => {
		expect(
			connectorForConnectionIds(groups, new Set(["1", "3"])),
		).toBeUndefined();
	});

	it("returns undefined for an empty or unmatched set", () => {
		expect(connectorForConnectionIds(groups, new Set())).toBeUndefined();
		expect(
			connectorForConnectionIds(groups, new Set(["999"])),
		).toBeUndefined();
	});

	it("returns undefined when any selected id is unmatched", () => {
		expect(
			connectorForConnectionIds(groups, new Set(["1", "999"])),
		).toBeUndefined();
	});
});

describe("parseConnectionScope", () => {
	it("keeps a connection filter when an agent filter is also present", () => {
		expect(
			parseConnectionScope({ agent: "scout", connection_ids: "1" }),
		).toBe("1");
	});
});

