1	// @vitest-environment jsdom
2	import { fireEvent, render, screen, waitFor } from '@testing-library/react';
3	import type * as React from 'react';
4	import { beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
5	
6	// Radix Popover uses pointer-capture APIs jsdom doesn't implement.
7	beforeAll(() => {
8	  const proto = Element.prototype as unknown as Record<string, unknown>;
9	  proto.hasPointerCapture ??= () => false;
10	  proto.setPointerCapture ??= () => {};
11	  proto.releasePointerCapture ??= () => {};
12	  proto.scrollIntoView ??= () => {};
13	});
14	
15	const navigate = vi.fn();
16	/** Mutable stand-in for the live URL search — tests set this before rendering. */
17	let locationSearch: Record<string, unknown> = {};
