export type MemoryScope =
	| { kind: "type"; slug: string }
	| { kind: "connection"; ids: string }
	| { kind: "agent"; id: string }
	| { kind: "entity"; path: string };

/**
 * Set one in-place scope on `/memory`, clear the other scopes, and preserve the
 * current view. `viewOverride` handles scopes that the current view cannot show.
 */
export function memoryScopeSearch(
	ownerSlug: string,
	scope: MemoryScope,
	currentSearch: Record<string, unknown> = {},
	viewOverride?: MemoryView,
) {
	const view =
		viewOverride ??
		(typeof currentSearch.view === "string"
			? (currentSearch.view as string)
			: undefined);
	return {
		to: "/$owner/memory" as const,
		params: { owner: ownerSlug },
		search: pruneSearch({
			view: view && view !== "entities" ? view : undefined,
			type: scope.kind === "type" ? scope.slug : undefined,
			connection_ids: scope.kind === "connection" ? scope.ids : undefined,
			agent: scope.kind === "agent" ? scope.id : undefined,
			entity: scope.kind === "entity" ? scope.path : undefined,
			// Drill-down keys never survive a scope change.
			behavior: undefined,
			schedule: undefined,
			platforms: undefined,
			feed_ids: undefined,
			run_ids: undefined,
			at: undefined,
		}) as Record<string, string | undefined>,
	};
}

/**
 * Additive scope for the Events view: apply a filter patch while preserving
 * sibling event filters already in the URL. This is what makes the Events
 * toolbar dropdowns COMBINABLE (type + connection_ids + feed_ids + agent AND
 * together) rather than mutually exclusive like `memoryScopeSearch`. A patch
 * value of `undefined` clears that key. Events-only — Feeds/Entities
 * stay single-scope via `memoryScopeSearch`/`memoryBrowseTypeSearch`.
 */
export function memoryEventsFilterSearch(
	ownerSlug: string,
	currentSearch: Record<string, unknown>,
	patch: Record<string, string | undefined>,
) {
	return {
		to: "/$owner/memory" as const,
		params: { owner: ownerSlug },
		search: pruneSearch({
			...currentSearch,
			view: "events",
			...patch,
		}) as Record<string, string | undefined>,
	};
}

/** Scope to an entity type (`?type=`), preserving the current view. */
export function memoryBrowseTypeSearch(
	ownerSlug: string,
	entityTypeSlug: string,
	currentSearch: Record<string, unknown> = {},
) {
	return memoryScopeSearch(
		ownerSlug,
		{ kind: "type", slug: entityTypeSlug },
		currentSearch,
	);
}

/** Scope to a single entity (`?entity=<type>/<slug>`), preserving the view. */
export function memoryBrowseEntitySearch(
	ownerSlug: string,
	segments: EntityPathSegment[],
	currentSearch: Record<string, unknown> = {},
) {
	return memoryScopeSearch(
		ownerSlug,
		{ kind: "entity", path: entityPathToBrowsePath(segments) },
		currentSearch,
	);
}

