import { Activity, Boxes, type LucideIcon, Plug } from "lucide-react";

/**
 * Owner-scoped nav sections — one icon + label shared by sidebar and page
 * headers. The sidebar is the site map: sections render in this order.
 *
 *  - **Activity** → the Events stream (`/activity`)
 *  - **Connect** → connectors + synthesized providers/sandboxes
 *  - **Memory** → entity types/records (`/memory`)
 */
export const OWNER_SECTIONS = {
	activity: {
		icon: Activity,
		label: "Activity",
		/** Router template. */
		to: "/$owner/activity",
		search: {} as Record<string, unknown>,
		/** Path segment under `/$owner/` used for matching. */
		segment: "activity",
	},
	connectors: {
		icon: Plug,
		label: "Connect",
		to: "/$owner/connectors",
		search: {} as Record<string, unknown>,
		segment: "connectors",
	},
	context: {
		icon: Boxes,
		label: "Memory",
		to: "/$owner/memory",
		search: {} as Record<string, unknown>,
		segment: "memory",
	},
} as const satisfies Record<
	string,
	{
		icon: LucideIcon;
		label: string;
		to: string;
		search: Record<string, unknown>;
		segment: string;
	}
>;

export type OwnerSectionKey = keyof typeof OWNER_SECTIONS;

/** Whether a sidebar section is active for the current path. */
export function isOwnerSectionActive(
	key: OwnerSectionKey,
	owner: string,
	pathname: string,
): boolean {
	const base = `/${owner}/${OWNER_SECTIONS[key].segment}`;
	return (
		pathname === base ||
		pathname === `${base}/` ||
		pathname.startsWith(`${base}/`)
	);
}

import { Link } from "@tanstack/react-router";
import { Boxes, ChevronRight, X } from "lucide-react";
import type { ReactNode } from "react";
import { EventsTab } from "@/components/entity-tabs/events-tab";
import { TabEmptyState } from "@/components/entity-tabs/tab-states";
import { MemberScopeGate } from "@/components/memory/member-scope-gate";
import { Button } from "@/components/ui/button";
import { EntityIcon } from "@/components/ui/entity-icon";
import { useOrgContext } from "@/hooks/use-org-context";
import { useAgentWatchersList } from "@/hooks/use-watchers";
import { useAgents, useEntityType, useResolvedPath } from "@/lib/api";
import { useSchedules } from "@/lib/api/schedules";
import { decodeEntityBrowsePath, decodeEntityTypeParam } from "@/lib/url";

/**
 * Activity content pane: the org-wide Events stream plus its scope drill-downs
 * (entity, agent → behavior/schedule). Additive event filters live in the
 * Events toolbar; this pane only resolves URL scopes and renders the header.
 */
export function ActivityPane({
	organizationId,
	ownerSlug,
	typeScope,
	entityScope,
	agentScope,
	watcherScope,
	scheduleScope,
}: {
	organizationId: string | null;
	ownerSlug: string;
	typeScope?: string;
	entityScope?: string;
	agentScope?: string;
	watcherScope?: string;
	scheduleScope?: string;
}) {
	const { orgContext } = useOrgContext();
	const { data: agents = [] } = useAgents();
	const agentLabel = agentScope
		? (agents.find((agent) => agent.agentId === agentScope)?.name ?? agentScope)
		: undefined;
	const { data: agentWatchers = [] } = useAgentWatchersList(agentScope, {
		includeDetails: false,
	});
	const watcherLabel = watcherScope
		? (agentWatchers.find((w) => w.behavior_id === watcherScope)?.name ??
			`Behavior ${watcherScope}`)
		: undefined;
	const { data: agentSchedules = [] } = useSchedules(agentScope);
	const scheduleLabel = scheduleScope
		? (agentSchedules.find((s) => s.id === scheduleScope)?.description ??
			"Schedule")
		: undefined;
	const typeSlug = typeScope ? decodeEntityTypeParam(typeScope) : undefined;
	const isMemberScope =
		typeSlug === "$member" || entityScope?.split("/")[0] === "$member";

	// Resolve the selected entity (if any) to its id, for the events filters.
	const {
		data: resolved,
		isLoading: entityLoading,
		error: entityError,
	} = useResolvedPath(
