import { memoryBrowseTypeSearch } from "@/lib/memory-browse";
import { pruneSearch } from "@/lib/router-search";
import { decodeEntityBrowsePath, decodeEntityTypeParam } from "@/lib/url";
import { MemberScopeGate } from "./member-scope-gate";
import { MemoryEntityDetail } from "./memory-entity-detail";

/**
 * Memory content pane: entity types and records ("Memory" in the sidebar).
 * The Events stream lives on its own page (`/activity`, `ActivityPane`).
 */
export function MemoryHomePane({
	ownerSlug,
	typeScope,
	entityScope,
	create,
	createType = false,
}: {
	ownerSlug: string;
	typeScope?: string;
	entityScope?: string;
	create: boolean;
	/** Create-entity-type subpage. */
	createType?: boolean;
}) {
	const navigate = useNavigate();
	const { orgContext } = useOrgContext();
	const typeSlug = typeScope ? decodeEntityTypeParam(typeScope) : undefined;
	const isMemberScope =
		typeSlug === "$member" || entityScope?.split("/")[0] === "$member";

	// Resolve the selected entity (if any) to its id + type for the detail render.
	const {
		data: resolved,
		isLoading: entityLoading,
		error: entityError,
	} = useResolvedPath(
		entityScope ? `/${ownerSlug}/${decodeEntityBrowsePath(entityScope)}` : "",
		orgContext,
	);
	const entity = entityScope ? resolved?.entity : undefined;
	// The `?entity=` scope points at nothing (deleted / bad slug): the resolve
	// settled with no entity and no in-flight fetch.
	const entityNotFound =
		entityScope != null &&
		!entityLoading &&
		(entityError != null || resolved?.entity == null);
	// The type whose icon labels the scope header — the scoped type, or the
	// selected entity's own type when an entity is scoped.
	const { data: scopeType } = useEntityType(
		entity?.entity_type ?? typeSlug ?? "",
		orgContext,
	);

	const closeCreateType = () => {
		void navigate({
			to: "/$owner/memory",
			params: { owner: ownerSlug },
			search: {},
		});
	};

	// Clear steps ONE level up the scope hierarchy (entity → its type list →
	// nothing), it doesn't nuke everything.
	//
