import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { createMemoryHistory, createRouter, RouterProvider } from "@tanstack/react-router";
import { http, HttpResponse } from "msw";
import { render, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { parseRouterSearch, stringifyRouterSearch } from "@/lib/router-search";
import { setAuthStateMock } from "@/test/auth-state-mock";
import { server } from "@/test/msw-server";

const OWNER = "test-org";

async function mountAt(path: string) {
	setAuthStateMock("authenticated");
	server.use(
		http.get("*/api/organizations", () =>
			HttpResponse.json({
				organizations: [
					{
						id: "org-1",
						name: "Test Org",
						slug: OWNER,
						logo: null,
						description: null,
						created_at: "2026-01-01T00:00:00.000Z",
						is_member: true,
						visibility: "private",
					},
				],
			}),
		),
	);

	const queryClient = new QueryClient({
		defaultOptions: {
			queries: { retry: false, staleTime: Number.POSITIVE_INFINITY },
		},
	});
	const { routeTree } = await import("@/routeTree.gen");
	const router = createRouter({
		routeTree,
		history: createMemoryHistory({ initialEntries: [path] }),
		context: { queryClient },
		parseSearch: parseRouterSearch,
		stringifySearch: stringifyRouterSearch,
		defaultPreload: false,
	});
	const result = render(
		<QueryClientProvider client={queryClient}>
			{/** biome-ignore lint/suspicious/noExplicitAny: memory router variant */}
			<RouterProvider router={router as any} />
		</QueryClientProvider>,
	);
	await waitFor(() => {
		expect(router.state.status).toBe("idle");
	});
	return { router, ...result };
}

describe("memory $member routing", () => {
	let errorSpy: ReturnType<typeof vi.spyOn>;
	beforeEach(() => {
		errorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
	});
	afterEach(() => errorSpy.mockRestore());

	it("redirects legacy splat /memory/%24member/<slug> to ?entity=$member/<slug>", async () => {
		const { router, unmount } = await mountAt(
			`/${OWNER}/memory/%24member/${OWNER}`,
		);
		expect(router.state.location.pathname).toBe(`/${OWNER}/memory`);
		expect(router.state.location.search).toMatchObject({
			entity: `$member/${OWNER}`,
		});
		expect(router.state.location.search.type).toBeUndefined();
		unmount();
	}, 20_000);

	it("canonicalizes ?entity=%24member/<slug> query scopes", async () => {
		const { router, unmount } = await mountAt(
			`/${OWNER}/memory?entity=%24member%2F${OWNER}`,
		);
		expect(router.state.location.pathname).toBe(`/${OWNER}/memory`);
		expect(router.state.location.search).toMatchObject({
			entity: `$member/${OWNER}`,
			view: "entities",
		});
		expect(router.state.location.search.type).toBeUndefined();
		unmount();
	}, 20_000);

	it("keeps a canonical member list URL stable", async () => {
		const { router, unmount } = await mountAt(
			`/${OWNER}/memory?type=$member`,
		);
		expect(router.state.location.pathname).toBe(`/${OWNER}/memory`);
		expect(router.state.location.search).toMatchObject({
			type: "$member",
		});
		unmount();
	}, 20_000);

	it("redirects legacy /members to the memory members scope", async () => {
		const { router, unmount } = await mountAt(`/${OWNER}/members`);
		expect(router.state.location.pathname).toBe(`/${OWNER}/memory`);
		expect(router.state.location.search).toMatchObject({
			type: "$member",
		});
		unmount();
	}, 20_000);

	it("redirects bare legacy /%24member to scoped memory", async () => {
		const { router, unmount } = await mountAt(`/${OWNER}/%24member`);
		expect(router.state.location.pathname).toBe(`/${OWNER}/memory`);
		expect(router.state.location.search.type).toBe("$member");
		unmount();
	}, 20_000);

	it("honors ?create=true after JSON search round-trip", async () => {
		const { router, unmount } = await mountAt(
			`/${OWNER}/memory?type=$member&create=true`,
		);
		const match = router.state.matches.find(
			(m) => m.routeId === "/$owner/memory/",
		);
		// `stringifyRouterSearch` JSON-parses `true`; validateSearch normalizes it.
		expect(match?.search).toMatchObject({
			type: "$member",
			create: "true",
		});
		unmount();
	}, 20_000);

	it("navigates to create mode without leaving a stale entity scope", async () => {
		const { router, unmount } = await mountAt(
			`/${OWNER}/memory?type=$member&entity=%24member%2F${OWNER}`,
		);
		expect(router.state.location.search).toMatchObject({
			entity: `$member/${OWNER}`,
		});
		await router.navigate({
			to: "/$owner/memory",
			params: { owner: OWNER },
			search: { type: "$member", create: "true" },
			replace: true,
		});
		await waitFor(() => {
			const match = router.state.matches.find(
				(m) => m.routeId === "/$owner/memory/",
			);
			expect(match?.search).toMatchObject({
				type: "$member",
				create: "true",
			});
			expect(match?.search?.entity).toBeUndefined();
		});
		unmount();
	}, 20_000);
});

