26	/**
27	 * The parsed shape of a `/memory/$` splat: the entity type slug (first segment)
28	 * and, for entity detail, the full path. A bare `/memory` (no splat) parses to
29	 * `{ typeSlug: undefined }` — the memory home.
30	 */
31	export type MemorySplat = {
32		/** Raw (still URL-encoded) first path segment — the entity type. */
33		typeSegment?: string;
34		/** Full path after `/memory/` — `type` or `type/slug/...`. */
35		path?: string;
36		/** True when the splat addresses a single entity (has a slug after the type). */
37		isEntityDetail: boolean;
38	};
