40	export function parseMemorySplat(splat: string | undefined): MemorySplat {
41		const trimmed = (splat ?? "").replace(/^\/+|\/+$/g, "");
42		if (!trimmed) return { isEntityDetail: false };
43		const segments = trimmed.split("/");
44		return {
45			typeSegment: segments[0],
46			path: trimmed,
47			isEntityDetail: segments.length > 1,
48		};
