import { describe, expect, it } from "vitest";
import { parsePeekHref } from "./parse-peek-href";

describe("parsePeekHref", () => {
	it("peeks a single-run memory permalink", () => {
		expect(parsePeekHref("/acme/memory?view=events&run_ids=42")).toEqual({
			kind: "memory",
			owner: "acme",
			runId: 42,
		});
	});

	it("does NOT peek a generic memory link with no run_ids (navigates instead)", () => {
		expect(parsePeekHref("/acme/memory")).toBeNull();
		expect(parsePeekHref("/acme/memory?view=events")).toBeNull();
		expect(parsePeekHref("/acme/memory?run_ids=")).toBeNull();
	});

	it("does NOT peek a memory link with an invalid run id", () => {
		expect(parsePeekHref("/acme/memory?run_ids=abc")).toBeNull();
		expect(parsePeekHref("/acme/memory?run_ids=0")).toBeNull();
		expect(parsePeekHref("/acme/memory?run_ids=-3")).toBeNull();
	});

	it("does NOT peek a multi-run memory link (navigates to the full list)", () => {
		expect(parsePeekHref("/acme/memory?run_ids=42,43")).toBeNull();
	});

	it("peeks a behavior href and parses its run_id / view", () => {
		expect(
			parsePeekHref(
				"/acme/agents/ag1/behaviors/w1?view=activity&run_id=7",
			),
		).toEqual({
			kind: "behavior",
			owner: "acme",
			agentId: "ag1",
			watcherId: "w1",
			view: "activity",
			runId: 7,
		});
	});

	it("returns null for an unrelated path", () => {
		expect(parsePeekHref("/acme/connections/slack")).toBeNull();
	});
});

