import { createFileRoute, redirect } from "@tanstack/react-router";
import { MemoryHomePane } from "@/components/memory/memory-home-pane";
import { OwnerWorkspaceGate } from "@/components/owner-workspace-gate";
import { useWorkspaceRoot } from "@/lib/api";
import {
	memorySearchNeedsCanonicalRedirect,
	parseEntityScope,
} from "@/lib/memory-browse";
import { pruneSearch } from "@/lib/router-search";
import { decodeEntityTypeParam } from "@/lib/url";

/** Event-filter keys that only mean something on the Activity page. */
const EVENTS_ONLY_KEYS = [
	"agent",
	"agent_id",
	"behavior",
	"schedule",
	"connection_ids",
	"feed_ids",
	"run_ids",
	"platforms",
	"at",
] as const;

function hasEventsShape(s: Record<string, unknown>): boolean {
	if (s.view === "events" || s.view === "feeds") return true;
	if (s.browse_view === "events") return true;
	return EVENTS_ONLY_KEYS.some(
		(key) => s[key] != null && String(s[key]).trim() !== "",
	);
}

export const Route = createFileRoute("/$owner/memory/")({
	loader: ({ context: { queryClient }, params }) => {
		void queryClient.prefetchQuery(
			useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
		);
	},
	// Migrate legacy browsing to the current model: the Events stream moved to
	// `/activity`, a `?browse_path` (an entity detail) becomes the
	// `/memory/<type>/<slug>` path; a bare `?browse_type` becomes the in-place
	// `?type=<slug>` scope.
	beforeLoad: ({ params, search }) => {
		const s = search as Record<string, unknown>;
		// Old `/memory?view=events` deep links (and any events-only filter, which
		// implied the Events view) live on the Activity page now.
		if (hasEventsShape(s)) {
			throw redirect({
				to: "/$owner/activity",
				params: { owner: params.owner },
				search: pruneSearch({
					...s,
					// Legacy `?browse_type` carried the type scope for the old
					// `browse_view=events` form.
					type:
						typeof s.browse_type === "string" && s.browse_type.trim()
							? decodeEntityTypeParam(s.browse_type.trim())
							: (s.type as string | undefined),
					view: undefined,
					create: undefined,
					create_type: undefined,
					browse_type: undefined,
					browse_view: undefined,
				}) as Record<string, string | undefined>,
				replace: true,
			});
		}
		// `?view=entities` is the only view left — strip it.
		if (typeof s.view === "string") {
			throw redirect({
				to: "/$owner/memory",
				params: { owner: params.owner },
				search: pruneSearch({ ...s, view: undefined }) as Record<
					string,
					string | undefined
				>,
				replace: true,
			});
		}
		const legacyDetail =
			typeof s.browse_path === "string" && s.browse_path.trim()
				? s.browse_path.trim()
				: undefined;
		if (legacyDetail) {
			throw redirect({
				to: "/$owner/memory/$",
				params: { owner: params.owner, _splat: legacyDetail },
				search: {},
				replace: true,
			});
		}
		const legacyType =
			typeof s.browse_type === "string" && s.browse_type.trim()
				? s.browse_type.trim()
				: undefined;
		if (legacyType) {
			throw redirect({
				to: "/$owner/memory",
				params: { owner: params.owner },
				search: pruneSearch({
					type: decodeEntityTypeParam(legacyType),
					create: s.create === true || s.create === "true" ? true : undefined,
				}) as Record<string, string | undefined>,
				replace: true,
			});
		}
		const canonical = memorySearchNeedsCanonicalRedirect(s);
		if (canonical) {
			throw redirect({
				to: "/$owner/memory",
				params: { owner: params.owner },
				search: canonical,
				replace: true,
			});
		}
	},
	component: MemoryPage,
	validateSearch: (search: Record<string, unknown>) => {
		const result = pruneSearch(search) as Record<string, string | undefined>;
		// `stringifyRouterSearch` JSON-parses primitive search values, so `?create=true`
		// round-trips as boolean `true` — normalize back to the string the UI reads.
		if (search.create === true || search.create === "true") {
			result.create = "true";
		}
		// Create-entity-type subpage.
		if (search.create_type === true || search.create_type === "true") {
			result.create_type = "true";
		}
		return result;
	},
});

function MemoryPage() {
	const { owner } = Route.useParams();
	const search = Route.useSearch();
	const typeScope =
		typeof search.type === "string" && search.type.trim()
			? decodeEntityTypeParam(search.type.trim())
			: undefined;
	const entityScope = parseEntityScope(search);
	const createType = search.create_type === "true";
	const create = search.create === "true";

	return (
		<div className="flex flex-1 flex-col gap-6 px-4 py-6 lg:px-6">
			<OwnerWorkspaceGate owner={owner}>
				{(props) => (
					<div className="flex min-h-0 min-w-0 flex-1 flex-col">
						<MemoryHomePane
							ownerSlug={props.ownerSlug}
							typeScope={typeScope}
							entityScope={entityScope}
							create={create}
							createType={createType}
						/>
					</div>
				)}
			</OwnerWorkspaceGate>
		</div>
	);
}

